/// Definitions of all built-in pragmas
#[derive(Clone, Copy, Debug)]
pub struct PragmaName {
    /// Name of pragma
    pub zName: &'static [u8],
    /// PragTyp_XXX value
    pub ePragTyp: u8,
    /// Zero or more PragFlg_XXX values
    pub mPragFlg: u8,
    /// Start of column names in pragCName[]
    pub iPragCName: u8,
    /// Num of col names. 0 means use pragma name
    pub nPragCName: u8,
    /// Extra argument
    pub iArg: u64,
}

/// When the 0x10 bit of PRAGMA optimize is set, any ANALYZE commands
/// will be run with an analysis_limit set to the lessor of the value of
/// the following macro or to the actual analysis_limit if it is non-zero,
/// in order to prevent PRAGMA optimize from running for too long.
const SQLITE_DEFAULT_OPTIMIZE_LIMIT: i32 = 2000;

/// Maximum number of errors reported by integrity_check by default.
const SQLITE_INTEGRITY_CHECK_ERROR_MAX: i32 = 100;

/// A C string held in a slice: the bytes up to the first NUL.
#[inline]
fn cstr(z: &[u8]) -> &[u8] {
    match z.iter().position(|&c| c == 0) {
        Some(n) => &z[..n],
        None => z,
    }
}

/// Interpret the given string as a safety level.  Return 0 for OFF,
/// 1 for ON or NORMAL, 2 for FULL, and 3 for EXTRA.  Return 1 for an empty
/// or unrecognized string argument.  The FULL and EXTRA option is
/// disallowed if the omitFull parameter it 1.
///
/// Note that the values returned are one less that the values that
/// should be passed into sqlite3BtreeSetSafetyLevel().  The is done
/// to support legacy SQL code.  The safety level used to be boolean
/// and older scripts may have used numbers 0 for OFF and 1 for ON.
fn getSafetyLevel(z: &[u8], omitFull: i32, dflt: u8) -> u8 {
    //                       123456789 123456789 123
    const zText: &[u8] = b"onoffalseyestruextrafull";
    const iOffset: [u8; 8] = [0, 1, 2, 4, 9, 12, 15, 20];
    const iLength: [u8; 8] = [2, 2, 3, 5, 3, 4, 5, 4];
    const iValue: [u8; 8] = [1, 0, 0, 0, 1, 1, 3, 2];
    //                     on no off false yes true extra full
    let z = cstr(z);
    if sqlite3Isdigit(z.first().copied().unwrap_or(0)) {
        return (sqlite3Atoi(Some(z)) != 0) as u8;
    }
    let n = z.len();
    for i in 0..iLength.len() {
        let off = iOffset[i] as usize;
        if iLength[i] as usize == n
            && zText[off..off + n].eq_ignore_ascii_case(z)
            && (omitFull == 0 || iValue[i] <= 1)
        {
            return iValue[i];
        }
    }
    dflt
}

/// C: `u8 sqlite3GetBoolean(const char *z, u8 dflt)`
///
/// Interpret the given string as a boolean value.
pub fn sqlite3GetBoolean(z: Option<&[u8]>, dflt: u8) -> u8 {
    (getSafetyLevel(z.unwrap_or(b""), 1, dflt) != 0) as u8
}

/// Interpret the given string as a locking mode value.
fn getLockingMode(z: Option<&[u8]>) -> i32 {
    if let Some(z) = z {
        if 0 == sqlite3StrICmp(Some(z), Some(b"exclusive")) {
            return PAGER_LOCKINGMODE_EXCLUSIVE;
        }
        if 0 == sqlite3StrICmp(Some(z), Some(b"normal")) {
            return PAGER_LOCKINGMODE_NORMAL;
        }
    }
    PAGER_LOCKINGMODE_QUERY
}

/// Interpret the given string as an auto-vacuum mode value.
///
/// The following strings, "none", "full" and "incremental" are
/// acceptable, as are their numeric equivalents: 0, 1 and 2 respectively.
fn getAutoVacuum(z: &[u8]) -> i32 {
    if 0 == sqlite3StrICmp(Some(z), Some(b"none")) {
        return BTREE_AUTOVACUUM_NONE;
    }
    if 0 == sqlite3StrICmp(Some(z), Some(b"full")) {
        return BTREE_AUTOVACUUM_FULL;
    }
    if 0 == sqlite3StrICmp(Some(z), Some(b"incremental")) {
        return BTREE_AUTOVACUUM_INCR;
    }
    let i = sqlite3Atoi(Some(z));
    (if (0..=2).contains(&i) { i } else { 0 }) as u8 as i32
}

/// Interpret the given string as a temp db location. Return 1 for file
/// backed temporary databases, 2 for the Red-Black tree in memory database
/// and 0 to use the compile-time default.
fn getTempStore(z: &[u8]) -> i32 {
    let c = z.first().copied().unwrap_or(0);
    if (b'0'..=b'2').contains(&c) {
        (c - b'0') as i32
    } else if sqlite3StrICmp(Some(z), Some(b"file")) == 0 {
        1
    } else if sqlite3StrICmp(Some(z), Some(b"memory")) == 0 {
        2
    } else {
        0
    }
}

/// Invalidate temp storage, either when the temp storage is changed
/// from default, or when 'file' and the temp_store_directory has changed
fn invalidateTempStorage(db: &mut Sqlite3) -> i32 {
    if let Some(pBt) = db.aDb[1].pBt.clone() {
        if db.autoCommit == 0 || sqlite3BtreeTxnState(db, &pBt) != SQLITE_TXN_NONE {
            errmsg!(
                db,
                b"temporary storage cannot be changed from within a transaction"
            );
            return SQLITE_ERROR;
        }
        sqlite3BtreeClose(db, &pBt);
        db.aDb[1].pBt = None;
        sqlite3ResetAllSchemasOfConnection(db);
    }
    SQLITE_OK
}

/// If the TEMP database is open, close it and mark the database schema
/// as needing reloading.  This must be done when using the SQLITE_TEMP_STORE
/// or DEFAULT_TEMP_STORE pragmas.
fn changeTempStorage(db: &mut Sqlite3, zStorageType: &[u8]) -> i32 {
    let ts = getTempStore(zStorageType);
    if db.temp_store as i32 == ts {
        return SQLITE_OK;
    }
    if invalidateTempStorage(db) != SQLITE_OK {
        return SQLITE_ERROR;
    }
    db.temp_store = ts as u8;
    SQLITE_OK
}

/// Set result column names for a pragma.
fn setPragmaResultColumnNames(v: &mut Vdbe, pPragma: &PragmaName) {
    let n = pPragma.nPragCName;
    sqlite3VdbeSetNumCols(v, if n == 0 { 1 } else { n as i32 });
    if n == 0 {
        sqlite3VdbeSetColName(v, 0, COLNAME_NAME, pPragma.zName);
    } else {
        let mut j = pPragma.iPragCName as usize;
        for i in 0..n as i32 {
            sqlite3VdbeSetColName(v, i, COLNAME_NAME, pragCName[j]);
            j += 1;
        }
    }
}

/// Generate code to return a single integer value.
fn returnSingleInt(v: &mut Vdbe, value: i64) {
    sqlite3VdbeAddInt64(v, 1, value);
    sqlite3VdbeAddOp2(v, OP_ResultRow, 1, 1);
}

/// Generate code to return a single text value.
fn returnSingleText(v: &mut Vdbe, zValue: Option<&[u8]>) {
    if let Some(z) = zValue {
        sqlite3VdbeLoadString(v, 1, z);
        sqlite3VdbeAddOp2(v, OP_ResultRow, 1, 1);
    }
}

/// Set the safety_level and pager flags for pager iDb.  Or if iDb<0
/// set these values for all pagers.
fn setAllPagerFlags(db: &mut Sqlite3) {
    if db.autoCommit != 0 {
        for i in 0..db.aDb.len() {
            if let Some(pBt) = db.aDb[i].pBt.clone() {
                let f = db.aDb[i].safety_level as u32 | (db.flags & PAGER_FLAGS_MASK as u64) as u32;
                sqlite3BtreeSetPagerFlags(db, &pBt, f);
            }
        }
    }
}

/// Return a human-readable name for a constraint resolution action.
fn actionName(action: u8) -> &'static [u8] {
    match action {
        OE_SetNull => b"SET NULL",
        OE_SetDflt => b"SET DEFAULT",
        OE_Cascade => b"CASCADE",
        OE_Restrict => b"RESTRICT",
        _ => {
            debug_assert!(action == OE_None);
            b"NO ACTION"
        }
    }
}

/// C: `const char * sqlite3JournalModename(int eMode)`
///
/// Parameter eMode must be one of the PAGER_JOURNALMODE_XXX constants
/// defined in pager.h. This function returns the associated lowercase
/// journal-mode name.
pub fn sqlite3JournalModename(eMode: i32) -> Option<ZStr> {
    const azModeName: [&[u8]; 6] = [
        b"delete",
        b"persist",
        b"off",
        b"truncate",
        b"memory",
        b"wal",
    ];
    debug_assert!(eMode >= 0 && eMode as usize <= azModeName.len());
    if eMode < 0 || eMode as usize >= azModeName.len() {
        return None;
    }
    Some(azModeName[eMode as usize].to_vec())
}

/// Locate a pragma in the aPragmaName[] array.
pub fn pragmaLocate(zName: &[u8]) -> Option<&'static PragmaName> {
    let mut lwr: i32 = 0;
    let mut upr: i32 = aPragmaName.len() as i32 - 1;
    let mut mid: i32 = 0;
    while lwr <= upr {
        mid = (lwr + upr) / 2;
        let rc = crate::util::sqlite3_stricmp(Some(zName), Some(aPragmaName[mid as usize].zName));
        if rc == 0 {
            break;
        }
        if rc < 0 {
            upr = mid - 1;
        } else {
            lwr = mid + 1;
        }
    }
    if lwr > upr {
        None
    } else {
        Some(&aPragmaName[mid as usize])
    }
}

/// Create zero or more entries in the output for the SQL functions
/// defined by FuncDef p (Rust: the pNext chain `p`).
fn pragmaFunclistLine(v: &mut Vdbe, p: &[FuncDefRef], isBuiltin: i32, showInternFuncs: bool) {
    let mut mask: u32 = SQLITE_DETERMINISTIC
        | SQLITE_DIRECTONLY
        | SQLITE_SUBTYPE
        | SQLITE_INNOCUOUS
        | SQLITE_FUNC_INTERNAL;
    if showInternFuncs {
        mask = 0xffffffff;
    }
    const azEnc: [Option<&[u8]>; 4] = [None, Some(b"utf8"), Some(b"utf16le"), Some(b"utf16be")];
    for p in p.iter() {
        if p.xSFunc.is_none() {
            continue;
        }
        if (p.funcFlags & SQLITE_FUNC_INTERNAL) != 0 && !showInternFuncs {
            continue;
        }
        let zType: &[u8] = if p.xValue.is_some() {
            b"w"
        } else if p.xFinalize.is_some() {
            b"a"
        } else {
            b"s"
        };
        sqlite3VdbeMultiLoad(
            v,
            1,
            b"sissii",
            &[
                PfArg::Str(Some(&p.zName)),
                PfArg::Int(isBuiltin as i64),
                PfArg::Str(Some(zType)),
                PfArg::Str(azEnc[(p.funcFlags & SQLITE_FUNC_ENCMASK) as usize]),
                PfArg::Int(p.nArg as i64),
                PfArg::Int(((p.funcFlags & mask) ^ SQLITE_INNOCUOUS) as i64),
            ],
        );
    }
}

/// Helper subroutine for PRAGMA integrity_check:
///
/// Generate code to output a single-column result row with a value of the
/// string held in register 3.  Decrement the result count in register 1
/// and halt if the maximum number of result rows have been issued.
fn integrityCheckResultRow(v: &mut Vdbe) -> i32 {
    sqlite3VdbeAddOp2(v, OP_ResultRow, 3, 1);
    let a = sqlite3VdbeCurrentAddr(v) + 2;
    let addr = sqlite3VdbeAddOp3(v, OP_IfPos, 1, a, 1);
    sqlite3VdbeAddOp0(v, OP_Halt);
    addr
}

/// Should table pTab be skipped when doing an integrity_check?
/// Return true or false.
///
/// If pObjTab is not null, the return true if pTab matches pObjTab.
///
/// If pObjTab is null, then return true only if pTab is an imposter table.
fn tableSkipIntegrityCheck(pTab: &TableRef, pObjTab: Option<&TableRef>) -> bool {
    match pObjTab {
        Some(o) => !Rc::ptr_eq(pTab, o),
        None => (pTab.borrow().tabFlags & TF_Imposter) != 0,
    }
}

/// Rust: write the (address, field) pairs of a VdbeOpList just added.
#[inline]
fn op(db: &mut Sqlite3, addr: i32) -> &mut VdbeOp {
    &mut db.v().aOp[addr as usize]
}

