/// C: `void sqlite3Pragma( Parse *pParse, Token *pId1, Token *pId2, Token *pValue, int minusFlag )`
///
/// Process a pragma statement.
///
/// Pragmas are of this form:
///
///      PRAGMA [schema.]id [= value]
///
/// The identifier might also be a string.  The value is a string, and
/// identifier, or a number.  If minusFlag is true, then the value is
/// a number that was preceded by a minus sign.
///
/// If the left side is "database.id" then pId1 is the database name
/// and pId2 is the id.  If the left side is just "id" then pId1 is the
/// id and pId2 is any empty string.
///
/// Rust: pValue is None for C NULL; internally a NULL pValue is handled
/// as a Token whose `z` is None.
pub fn sqlite3Pragma(
    db: &mut Sqlite3,
    pId1: &Token,
    pId2: &Token,
    pValue: Option<&Token>,
    minusFlag: i32,
) {
    let tValue: Token = pValue.cloned().unwrap_or_default();
    let pValue: &Token = &tValue;
    if !crate::select::sqlite3GetVdbe(db) {
        return;
    }
    sqlite3VdbeRunOnlyOnce(db.v());
    db.pp().nMem = 2;

    // Interpret the [schema.] part of the pragma statement. iDb is the
    // index of the database this pragma is being applied to in db.aDb[].
    let mut pId: Token = Token::default();
    let mut iDb = crate::build::sqlite3TwoPartName(db, pId1, pId2, &mut pId);
    if iDb < 0 {
        return;
    }

    // If the temp database has been explicitly named as part of the
    // pragma, make sure it is open.
    if iDb == 1 && crate::build::sqlite3OpenTempDatabase(db) != 0 {
        return;
    }

    let Some(zLeft) = sqlite3NameFromToken(db, &pId) else {
        return;
    };
    let zRight: Option<ZStr> = if minusFlag != 0 {
        Some(mprintf!(db, b"-%T", pValue))
    } else {
        sqlite3NameFromToken(db, pValue)
    };
    let zRight = zRight.as_deref();

    let mut id2n = pId2.n;
    let mut zDb: Option<ZStr> = if pId2.n > 0 {
        db.aDb[iDb as usize].zDbSName.clone()
    } else {
        None
    };
    if crate::auth::sqlite3AuthCheck(db, SQLITE_PRAGMA, Some(&zLeft), zRight, zDb.as_deref()) != 0 {
        return;
    }

    // Send an SQLITE_FCNTL_PRAGMA file-control to the underlying VFS
    // connection.  If it returns SQLITE_OK, then assume that the VFS
    // handled the pragma and generate a no-op prepared statement.
    //
    // IMPLEMENTATION-OF: R-12238-55120 Whenever a PRAGMA statement is parsed,
    // an SQLITE_FCNTL_PRAGMA file control is sent to the open sqlite3_file
    // object corresponding to the database file to which the pragma
    // statement refers.
    //
    // Rust: the built-in VFS does not implement SQLITE_FCNTL_PRAGMA (the C
    // unix VFS returns SQLITE_NOTFOUND for it), and the char** argument
    // cannot be passed through sqlite3_file_control(); the file control is
    // therefore always "not found".
    db.busyHandler.borrow_mut().nBusy = 0;
    let rc = SQLITE_NOTFOUND;
    if rc != SQLITE_NOTFOUND {
        let p = db.pp();
        p.nErr += 1;
        p.rc = rc;
        return;
    }

    // Locate the pragma in the lookup table
    let Some(pPragma) = pragmaLocate(&zLeft) else {
        // IMP: R-43042-22504 No error messages are generated if an
        // unknown pragma is issued.
        return;
    };

    // Make sure the database schema is loaded if the pragma requires that
    if (pPragma.mPragFlg & PragFlg_NeedSchema) != 0 {
        if crate::prepare::sqlite3ReadSchema(db) != 0 {
            return;
        }
    }

    // Register the result column names for pragmas that return results
    if (pPragma.mPragFlg & PragFlg_NoColumns) == 0
        && ((pPragma.mPragFlg & PragFlg_NoColumns1) == 0 || zRight.is_none())
    {
        setPragmaResultColumnNames(db.v(), pPragma);
    }

    let pDbBt: Option<BtreeP> = db.aDb[iDb as usize].pBt.clone();

    // Jump to the appropriate pragma handler
    match pPragma.ePragTyp {
        // PRAGMA [schema.]default_cache_size
        // PRAGMA [schema.]default_cache_size=N
        //
        // The first form reports the current persistent setting for the
        // page cache size.  The value returned is the maximum number of
        // pages in the page cache.  The second form sets both the current
        // page cache size value and the persistent page cache size value
        // stored in the database file.
        //
        // Older versions of SQLite would set the default cache size to a
        // negative number to indicate synchronous=OFF.  These days,
        // synchronous is always on by default regardless of the sign of
        // the default cache size.  But continue to take the absolute value
        // of the default cache size of historical compatibility.
        PragTyp_DEFAULT_CACHE_SIZE => {
            const getCacheSize: [VdbeOpList; 9] = [
                VdbeOpList {
                    opcode: OP_Transaction,
                    p1: 0,
                    p2: 0,
                    p3: 0,
                }, // 0
                VdbeOpList {
                    opcode: OP_ReadCookie,
                    p1: 0,
                    p2: 1,
                    p3: BTREE_DEFAULT_CACHE_SIZE as i8,
                }, // 1
                VdbeOpList {
                    opcode: OP_IfPos,
                    p1: 1,
                    p2: 8,
                    p3: 0,
                },
                VdbeOpList {
                    opcode: OP_Integer,
                    p1: 0,
                    p2: 2,
                    p3: 0,
                },
                VdbeOpList {
                    opcode: OP_Subtract,
                    p1: 1,
                    p2: 2,
                    p3: 1,
                },
                VdbeOpList {
                    opcode: OP_IfPos,
                    p1: 1,
                    p2: 8,
                    p3: 0,
                },
                VdbeOpList {
                    opcode: OP_Integer,
                    p1: 0,
                    p2: 1,
                    p3: 0,
                }, // 6
                VdbeOpList {
                    opcode: OP_Noop,
                    p1: 0,
                    p2: 0,
                    p3: 0,
                },
                VdbeOpList {
                    opcode: OP_ResultRow,
                    p1: 1,
                    p2: 1,
                    p3: 0,
                },
            ];
            sqlite3VdbeUsesBtree(db.v(), iDb);
            match zRight {
                None => {
                    db.pp().nMem += 2;
                    let a = sqlite3VdbeAddOpList(db.v(), &getCacheSize, 0);
                    op(db, a).p1 = iDb;
                    op(db, a + 1).p1 = iDb;
                    op(db, a + 6).p1 = SQLITE_DEFAULT_CACHE_SIZE;
                }
                Some(zr) => {
                    let size = crate::util::sqlite3AbsInt32(sqlite3Atoi(Some(zr)));
                    sqlite3BeginWriteOperation(db, 0, iDb);
                    sqlite3VdbeAddOp3(db.v(), OP_SetCookie, iDb, BTREE_DEFAULT_CACHE_SIZE, size);
                    db.aDb[iDb as usize].pSchema.borrow_mut().cache_size = size;
                    if let Some(pBt) = &pDbBt {
                        sqlite3BtreeSetCacheSize(db, pBt, size);
                    }
                }
            }
        }

        // PRAGMA [schema.]page_size
        // PRAGMA [schema.]page_size=N
        //
        // The first form reports the current setting for the
        // database page size in bytes.  The second form sets the
        // database page size value.  The value can only be set if
        // the database has not yet been created.
        PragTyp_PAGE_SIZE => {
            let pBt = pDbBt.clone().expect("btree");
            match zRight {
                None => {
                    let size = sqlite3BtreeGetPageSize(&pBt);
                    returnSingleInt(db.v(), size as i64);
                }
                Some(zr) => {
                    // Malloc may fail when setting the page-size, as there is
                    // an internal buffer that the pager module resizes using
                    // sqlite3_realloc().
                    db.nextPagesize = sqlite3Atoi(Some(zr));
                    if SQLITE_NOMEM == sqlite3BtreeSetPageSize(&pBt, db.nextPagesize, 0, 0) {
                        // sqlite3OomFault(db)
                    }
                }
            }
        }

        // PRAGMA [schema.]secure_delete
        // PRAGMA [schema.]secure_delete=ON/OFF/FAST
        //
        // The first form reports the current setting for the
        // secure_delete flag.  The second form changes the secure_delete
        // flag setting and reports the new value.
        PragTyp_SECURE_DELETE => {
            let pBt = pDbBt.clone().expect("btree");
            let mut b = -1;
            if let Some(zr) = zRight {
                if crate::util::sqlite3_stricmp(Some(zr), Some(b"fast")) == 0 {
                    b = 2;
                } else {
                    b = sqlite3GetBoolean(Some(zr), 0) as i32;
                }
            }
            if id2n == 0 && b >= 0 {
                for ii in 0..db.aDb.len() {
                    if let Some(p) = db.aDb[ii].pBt.clone() {
                        sqlite3BtreeSecureDelete(&p, b);
                    }
                }
            }
            b = sqlite3BtreeSecureDelete(&pBt, b);
            returnSingleInt(db.v(), b as i64);
        }

        // PRAGMA [schema.]max_page_count
        // PRAGMA [schema.]max_page_count=N
        //
        // The first form reports the current setting for the
        // maximum number of pages in the database file.  The
        // second form attempts to change this setting.  Both
        // forms return the current setting.
        //
        // The absolute value of N is used.  This is undocumented and might
        // change.  The only purpose is to provide an easy way to test
        // the sqlite3AbsInt32() function.
        //
        // PRAGMA [schema.]page_count
        //
        // Return the number of pages in the specified database.
        PragTyp_PAGE_COUNT => {
            let mut x: i64 = 0;
            sqlite3CodeVerifySchema(db, iDb);
            let iReg = {
                let p = db.pp();
                p.nMem += 1;
                p.nMem
            };
            if sqlite3Tolower(zLeft.first().copied().unwrap_or(0)) == b'p' {
                sqlite3VdbeAddOp2(db.v(), OP_Pagecount, iDb, iReg);
            } else {
                match zRight {
                    Some(zr) if sqlite3DecOrHexToI64(Some(zr), &mut x) == 0 => {
                        if x < 0 {
                            x = 0;
                        } else if x > 0xfffffffe {
                            x = 0xfffffffe;
                        }
                    }
                    _ => {
                        x = 0;
                    }
                }
                sqlite3VdbeAddOp3(db.v(), OP_MaxPgcnt, iDb, iReg, x as i32);
            }
            sqlite3VdbeAddOp2(db.v(), OP_ResultRow, iReg, 1);
        }

        // PRAGMA [schema.]locking_mode
        // PRAGMA [schema.]locking_mode = (normal|exclusive)
        PragTyp_LOCKING_MODE => {
            let mut zRet: &[u8] = b"normal";
            let mut eMode = getLockingMode(zRight);

            if id2n == 0 && eMode == PAGER_LOCKINGMODE_QUERY {
                // Simple "PRAGMA locking_mode;" statement. This is a query for
                // the current default locking mode (which may be different to
                // the locking-mode of the main database).
                eMode = db.dfltLockMode as i32;
            } else {
                if id2n == 0 {
                    // This indicates that no database name was specified as part
                    // of the PRAGMA command. In this case the locking-mode must be
                    // set on all attached databases, as well as the main db file.
                    //
                    // Also, the sqlite3.dfltLockMode variable is set so that
                    // any subsequently attached databases also use the specified
                    // locking mode.
                    debug_assert!(iDb == 0);
                    for ii in 2..db.aDb.len() {
                        if let Some(p) = db.aDb[ii].pBt.clone() {
                            let pPager = sqlite3BtreePager(&p);
                            crate::pager::sqlite3PagerLockingMode(&mut pPager.borrow_mut(), eMode);
                        }
                    }
                    db.dfltLockMode = eMode as u8;
                }
                let pPager = sqlite3BtreePager(pDbBt.as_ref().expect("btree"));
                eMode = crate::pager::sqlite3PagerLockingMode(&mut pPager.borrow_mut(), eMode);
            }

            debug_assert!(
                eMode == PAGER_LOCKINGMODE_NORMAL || eMode == PAGER_LOCKINGMODE_EXCLUSIVE
            );
            if eMode == PAGER_LOCKINGMODE_EXCLUSIVE {
                zRet = b"exclusive";
            }
            returnSingleText(db.v(), Some(zRet));
        }

        // PRAGMA [schema.]journal_mode
        // PRAGMA [schema.]journal_mode =
        //                     (delete|persist|off|truncate|memory|wal|off)
        PragTyp_JOURNAL_MODE => {
            let mut eMode: i32; // One of the PAGER_JOURNALMODE_XXX symbols

            match zRight {
                None => {
                    // If there is no "=MODE" part of the pragma, do a query for
                    // the current mode
                    eMode = PAGER_JOURNALMODE_QUERY;
                }
                Some(zr) => {
                    let n = zr.len() as i32;
                    eMode = 0;
                    let mut found = false;
                    while let Some(zMode) = sqlite3JournalModename(eMode) {
                        if crate::util::sqlite3_strnicmp(Some(zr), Some(&zMode), n) == 0 {
                            found = true;
                            break;
                        }
                        eMode += 1;
                    }
                    if !found {
                        // If the "=MODE" part does not match any known journal
                        // mode, then do a query
                        eMode = PAGER_JOURNALMODE_QUERY;
                    }
                    if eMode == PAGER_JOURNALMODE_OFF && (db.flags & SQLITE_Defensive) != 0 {
                        // Do not allow journal-mode "OFF" in defensive since the
                        // database can become corrupted using ordinary SQL when
                        // the journal is off
                        eMode = PAGER_JOURNALMODE_QUERY;
                    }
                }
            }
            if eMode == PAGER_JOURNALMODE_QUERY && id2n == 0 {
                // Convert "PRAGMA journal_mode" into "PRAGMA main.journal_mode"
                iDb = 0;
                id2n = 1;
            }
            let mut ii = db.nDb() - 1;
            while ii >= 0 {
                if db.aDb[ii as usize].pBt.is_some() && (ii == iDb || id2n == 0) {
                    sqlite3VdbeUsesBtree(db.v(), ii);
                    sqlite3VdbeAddOp3(db.v(), OP_JournalMode, ii, 1, eMode);
                }
                ii -= 1;
            }
            sqlite3VdbeAddOp2(db.v(), OP_ResultRow, 1, 1);
        }

        // PRAGMA [schema.]journal_size_limit
        // PRAGMA [schema.]journal_size_limit=N
        //
        // Get or set the size limit on rollback journal files.
        PragTyp_JOURNAL_SIZE_LIMIT => {
            let pPager = sqlite3BtreePager(pDbBt.as_ref().expect("btree"));
            let mut iLimit: i64 = -2;
            if let Some(zr) = zRight {
                sqlite3DecOrHexToI64(Some(zr), &mut iLimit);
                if iLimit < -1 {
                    iLimit = -1;
                }
            }
            iLimit = crate::pager::sqlite3PagerJournalSizeLimit(&mut pPager.borrow_mut(), iLimit);
            returnSingleInt(db.v(), iLimit);
        }

        // PRAGMA [schema.]auto_vacuum
        // PRAGMA [schema.]auto_vacuum=N
        //
        // Get or set the value of the database 'auto-vacuum' parameter.
        // The value is one of:  0 NONE 1 FULL 2 INCREMENTAL
        PragTyp_AUTO_VACUUM => {
            let pBt = pDbBt.clone().expect("btree");
            match zRight {
                None => {
                    let x = sqlite3BtreeGetAutoVacuum(&pBt);
                    returnSingleInt(db.v(), x as i64);
                }
                Some(zr) => {
                    let eAuto = getAutoVacuum(zr);
                    debug_assert!((0..=2).contains(&eAuto));
                    db.nextAutovac = eAuto as u8 as i8;
                    // Call SetAutoVacuum() to set initialize the internal auto
                    // and incr-vacuum flags. This is required in case this
                    // connection creates the database file. It is important
                    // that it is created as an auto-vacuum capable db.
                    let rc = sqlite3BtreeSetAutoVacuum(&pBt, eAuto);
                    if rc == SQLITE_OK && (eAuto == 1 || eAuto == 2) {
                        // When setting the auto_vacuum mode to either "full" or
                        // "incremental", write the value of meta[6] in the
                        // database file. Before writing to meta[6], check that
                        // meta[3] indicates that this really is an auto-vacuum
                        // capable database.
                        const setMeta6: [VdbeOpList; 5] = [
                            VdbeOpList {
                                opcode: OP_Transaction,
                                p1: 0,
                                p2: 1,
                                p3: 0,
                            }, // 0
                            VdbeOpList {
                                opcode: OP_ReadCookie,
                                p1: 0,
                                p2: 1,
                                p3: BTREE_LARGEST_ROOT_PAGE as i8,
                            },
                            VdbeOpList {
                                opcode: OP_If,
                                p1: 1,
                                p2: 0,
                                p3: 0,
                            }, // 2
                            VdbeOpList {
                                opcode: OP_Halt,
                                p1: SQLITE_OK as i8,
                                p2: OE_Abort as i8,
                                p3: 0,
                            }, // 3
                            VdbeOpList {
                                opcode: OP_SetCookie,
                                p1: 0,
                                p2: BTREE_INCR_VACUUM as i8,
                                p3: 0,
                            }, // 4
                        ];
                        let iAddr = sqlite3VdbeCurrentAddr(db.v());
                        let a = sqlite3VdbeAddOpList(db.v(), &setMeta6, 0);
                        op(db, a).p1 = iDb;
                        op(db, a + 1).p1 = iDb;
                        op(db, a + 2).p2 = iAddr + 4;
                        op(db, a + 4).p1 = iDb;
                        op(db, a + 4).p3 = eAuto - 1;
                        sqlite3VdbeUsesBtree(db.v(), iDb);
                    }
                }
            }
        }

        // PRAGMA [schema.]incremental_vacuum(N)
        //
        // Do N steps of incremental vacuuming on a database.
        PragTyp_INCREMENTAL_VACUUM => {
            let mut iLimit = 0;
            if zRight.is_none() || sqlite3GetInt32(zRight, &mut iLimit) == 0 || iLimit <= 0 {
                iLimit = 0x7fffffff;
            }
            sqlite3BeginWriteOperation(db, 0, iDb);
            let v = db.v();
            sqlite3VdbeAddOp2(v, OP_Integer, iLimit, 1);
            let addr = sqlite3VdbeAddOp1(v, OP_IncrVacuum, iDb);
            sqlite3VdbeAddOp1(v, OP_ResultRow, 1);
            sqlite3VdbeAddOp2(v, OP_AddImm, 1, -1);
            sqlite3VdbeAddOp2(v, OP_IfPos, 1, addr);
            sqlite3VdbeJumpHere(v, addr);
        }

        // PRAGMA [schema.]cache_size
        // PRAGMA [schema.]cache_size=N
        //
        // The first form reports the current local setting for the
        // page cache size. The second form sets the local
        // page cache size value.  If N is positive then that is the
        // number of pages in the cache.  If N is negative, then the
        // number of pages is adjusted so that the cache uses -N kibibytes
        // of memory.
        PragTyp_CACHE_SIZE => match zRight {
            None => {
                let n = db.aDb[iDb as usize].pSchema.borrow().cache_size;
                returnSingleInt(db.v(), n as i64);
            }
            Some(zr) => {
                let size = sqlite3Atoi(Some(zr));
                db.aDb[iDb as usize].pSchema.borrow_mut().cache_size = size;
                if let Some(pBt) = &pDbBt {
                    sqlite3BtreeSetCacheSize(db, pBt, size);
                }
            }
        },

        // PRAGMA [schema.]cache_spill
        // PRAGMA cache_spill=BOOLEAN
        // PRAGMA [schema.]cache_spill=N
        //
        // The first form reports the current local setting for the
        // page cache spill size. The second form turns cache spill on
        // or off.  When turning cache spill on, the size is set to the
        // current cache_size.  The third form sets a spill size that
        // may be different form the cache size.
        // If N is positive then that is the
        // number of pages in the cache.  If N is negative, then the
        // number of pages is adjusted so that the cache uses -N kibibytes
        // of memory.
        //
        // If the number of cache_spill pages is less then the number of
        // cache_size pages, no spilling occurs until the page count exceeds
        // the number of cache_size pages.
        //
        // The cache_spill=BOOLEAN setting applies to all attached schemas,
        // not just the schema specified.
        PragTyp_CACHE_SPILL => match zRight {
            None => {
                let x = if (db.flags & SQLITE_CacheSpill) == 0 {
                    0
                } else {
                    match &pDbBt {
                        Some(pBt) => sqlite3BtreeSetSpillSize(db, pBt, 0),
                        None => 0,
                    }
                };
                returnSingleInt(db.v(), x as i64);
            }
            Some(zr) => {
                let mut size = 1;
                if sqlite3GetInt32(Some(zr), &mut size) != 0 {
                    if let Some(pBt) = &pDbBt {
                        sqlite3BtreeSetSpillSize(db, pBt, size);
                    }
                }
                if sqlite3GetBoolean(Some(zr), (size != 0) as u8) != 0 {
                    db.flags |= SQLITE_CacheSpill;
                } else {
                    db.flags &= !SQLITE_CacheSpill;
                }
                setAllPagerFlags(db);
            }
        },

        // PRAGMA [schema.]mmap_size(N)
        //
        // Used to set mapping size limit. The mapping size limit is
        // used to limit the aggregate size of all memory mapped regions of the
        // database file. If this parameter is set to zero, then memory mapping
        // is not used at all.  If N is negative, then the default memory map
        // limit determined by sqlite3_config(SQLITE_CONFIG_MMAP_SIZE) is set.
        // The parameter N is measured in bytes.
        //
        // This value is advisory.  The underlying VFS is free to memory map
        // as little or as much as it wants.  Except, if N is set to 0 then the
        // upper layers will never invoke the xFetch interfaces to the VFS.
        PragTyp_MMAP_SIZE => {
            let mut sz: i64 = 0;
            if let Some(zr) = zRight {
                sqlite3DecOrHexToI64(Some(zr), &mut sz);
                if sz < 0 {
                    sz = crate::global::sqlite3GlobalConfig().szMmap;
                }
                if id2n == 0 {
                    db.szMmap = sz;
                }
                let mut ii = db.nDb() - 1;
                while ii >= 0 {
                    if let Some(p) = db.aDb[ii as usize].pBt.clone() {
                        if ii == iDb || id2n == 0 {
                            sqlite3BtreeSetMmapLimit(db, &p, sz);
                        }
                    }
                    ii -= 1;
                }
            }
            sz = -1;
            let rc = crate::mainapi::sqlite3_file_control(
                db,
                zDb.as_deref(),
                SQLITE_FCNTL_MMAP_SIZE,
                crate::os::FcntlArg::I64(&mut sz),
            );
            if rc == SQLITE_OK {
                returnSingleInt(db.v(), sz);
            } else if rc != SQLITE_NOTFOUND {
                let p = db.pp();
                p.nErr += 1;
                p.rc = rc;
            }
        }

        // PRAGMA temp_store
        // PRAGMA temp_store = "default"|"memory"|"file"
        //
        // Return or set the local value of the temp_store flag.  Changing
        // the local value does not make changes to the disk file and the
        // default value will be restored the next time the database is
        // opened.
        //
        // Note that it is possible for the library compile-time options to
        // override this setting
        PragTyp_TEMP_STORE => match zRight {
            None => {
                let t = db.temp_store;
                returnSingleInt(db.v(), t as i64);
            }
            Some(zr) => {
                changeTempStorage(db, zr);
            }
        },

        // PRAGMA temp_store_directory
        // PRAGMA temp_store_directory = ""|"directory_name"
        //
        // Return or set the local value of the temp_store_directory flag.
        // Changing the value sets a specific directory to be used for
        // temporary files.  Setting to a null string reverts to the default
        // temporary directory search.  If temporary directory is changed,
        // then invalidateTempStorage.
        PragTyp_TEMP_STORE_DIRECTORY => match zRight {
            None => {
                let d = crate::mainapi::sqlite3_temp_directory
                    .lock()
                    .unwrap()
                    .clone();
                returnSingleText(db.v(), d.as_deref());
            }
            Some(zr) => {
                if !zr.is_empty() {
                    let mut res = 0;
                    let pVfs = db.pVfs.clone();
                    let rc =
                        crate::os::sqlite3OsAccess(&pVfs, zr, SQLITE_ACCESS_READWRITE, &mut res);
                    if rc != SQLITE_OK || res == 0 {
                        errmsg!(db, b"not a writable directory");
                        return;
                    }
                }
                if SQLITE_TEMP_STORE == 0
                    || (SQLITE_TEMP_STORE == 1 && db.temp_store <= 1)
                    || (SQLITE_TEMP_STORE == 2 && db.temp_store == 1)
                {
                    invalidateTempStorage(db);
                }
                let mut d = crate::mainapi::sqlite3_temp_directory.lock().unwrap();
                *d = if !zr.is_empty() {
                    Some(zr.to_vec())
                } else {
                    None
                };
            }
        },

        // PRAGMA [schema.]synchronous
        // PRAGMA [schema.]synchronous=OFF|ON|NORMAL|FULL|EXTRA
        //
        // Return or set the local value of the synchronous flag.  Changing
        // the local value does not make changes to the disk file and the
        // default value will be restored the next time the database is
        // opened.
        PragTyp_SYNCHRONOUS => match zRight {
            None => {
                let l = db.aDb[iDb as usize].safety_level as i64 - 1;
                returnSingleInt(db.v(), l);
            }
            Some(zr) => {
                if db.autoCommit == 0 {
                    errmsg!(db, b"Safety level may not be changed inside a transaction");
                } else if iDb != 1 {
                    let mut iLevel: i32 = if sqlite3Isdigit(zr.first().copied().unwrap_or(0)) {
                        sqlite3Atoi(Some(zr))
                    } else {
                        getSafetyLevel(zr, 0, 1) as i32
                    };
                    iLevel = (iLevel + 1) & PAGER_SYNCHRONOUS_MASK;
                    if iLevel == 0 {
                        iLevel = 1;
                    }
                    db.aDb[iDb as usize].safety_level = iLevel as u8;
                    db.aDb[iDb as usize].bSyncSet = 1;
                    setAllPagerFlags(db);
                }
            }
        },

        PragTyp_FLAG => match zRight {
            None => {
                setPragmaResultColumnNames(db.v(), pPragma);
                let x = ((db.flags & pPragma.iArg) != 0) as i64;
                returnSingleInt(db.v(), x);
            }
            Some(zr) => {
                let mut mask: u64 = pPragma.iArg; // Mask of bits to set or clear.
                if db.autoCommit == 0 {
                    // Foreign key support may not be enabled or disabled while
                    // not in auto-commit mode.
                    mask &= !SQLITE_ForeignKeys;
                }

                if sqlite3GetBoolean(Some(zr), 0) != 0 {
                    if (mask & SQLITE_WriteSchema) == 0 || (db.flags & SQLITE_Defensive) == 0 {
                        db.flags |= mask;
                    }
                } else {
                    db.flags &= !mask;
                    if mask == SQLITE_DeferFKs {
                        db.nDeferredImmCons = 0;
                        db.nDeferredCons = 0;
                    }
                    if (mask & SQLITE_WriteSchema) != 0
                        && crate::util::sqlite3_stricmp(Some(zr), Some(b"reset")) == 0
                    {
                        // IMP: R-60817-01178 If the argument is "RESET" then
                        // schema writing is disabled (as with "PRAGMA
                        // writable_schema=OFF") and, in addition, the schema is
                        // reloaded.
                        sqlite3ResetAllSchemasOfConnection(db);
                    }
                }

                // Many of the flag-pragmas modify the code generated by the SQL
                // compiler (eg. count_changes). So add an opcode to expire all
                // compiled SQL statements after modifying a pragma value.
                sqlite3VdbeAddOp0(db.v(), OP_Expire);
                setAllPagerFlags(db);
            }
        },

        // PRAGMA table_info(<table>)
        //
        // Return a single row for each column of the named table. The
        // columns of the returned data set are:
        //
        // cid:        Column id (numbered from left to right, starting at 0)
        // name:       Column name
        // type:       Column declaration type.
        // notnull:    True if 'NOT NULL' is part of column declaration
        // dflt_value: The default value for the column, if any.
        // pk:         Non-zero for PK fields.
        PragTyp_TABLE_INFO => {
            if let Some(zr) = zRight {
                sqlite3CodeVerifyNamedSchema(db, zDb.as_deref());
                let pTab = sqlite3LocateTable(db, LOCATE_NOERR as u32, Some(zr), zDb.as_deref());
                if let Some(pTab) = pTab {
                    let mut nHidden = 0;
                    let pPk = sqlite3PrimaryKeyIndex(&pTab);
                    db.pp().nMem = 7;
                    crate::build::sqlite3ViewGetColumnNames(db, &pTab);
                    let nCol = pTab.borrow().nCol as i32;
                    for i in 0..nCol {
                        let mut isHidden = 0;
                        let mut pCol = pTab.borrow().aCol[i as usize].clone();
                        if (pCol.colFlags & COLFLAG_NOINSERT) != 0 {
                            if pPragma.iArg == 0 {
                                nHidden += 1;
                                continue;
                            }
                            if (pCol.colFlags & COLFLAG_VIRTUAL) != 0 {
                                isHidden = 2; // GENERATED ALWAYS AS ... VIRTUAL
                            } else if (pCol.colFlags & COLFLAG_STORED) != 0 {
                                isHidden = 3; // GENERATED ALWAYS AS ... STORED
                            } else {
                                debug_assert!((pCol.colFlags & COLFLAG_HIDDEN) != 0);
                                isHidden = 1; // HIDDEN
                            }
                        }
                        let k: i32 = if (pCol.colFlags & COLFLAG_PRIMKEY) == 0 {
                            0
                        } else {
                            match &pPk {
                                None => 1,
                                Some(pPk) => {
                                    let pk = pPk.borrow();
                                    let mut k = 1;
                                    while k <= nCol && pk.aiColumn[(k - 1) as usize] as i32 != i {
                                        k += 1;
                                    }
                                    k
                                }
                            }
                        };
                        let pColExpr = crate::build::sqlite3ColumnExpr(db, &pTab, i as usize);
                        let zDflt: Option<ZStr> = if isHidden >= 2 || pColExpr.is_null() {
                            None
                        } else {
                            db.ex(pColExpr).u.zToken.clone()
                        };
                        let zType = crate::util::sqlite3ColumnType(&mut pCol, Some(b""));
                        let mut args = vec![
                            PfArg::Int((i - nHidden) as i64),
                            PfArg::Str(Some(&pCol.zCnName)),
                            PfArg::Str(zType.as_deref()),
                            PfArg::Int((pCol.notNull != 0) as i64),
                            PfArg::Str(zDflt.as_deref()),
                            PfArg::Int(k as i64),
                        ];
                        if pPragma.iArg != 0 {
                            args.push(PfArg::Int(isHidden as i64));
                        }
                        let zTypes: &[u8] = if pPragma.iArg != 0 {
                            b"issisii"
                        } else {
                            b"issisi"
                        };
                        sqlite3VdbeMultiLoad(db.v(), 1, zTypes, &args);
                    }
                }
            }
        }

        // PRAGMA table_list
        //
        // Return a single row for each table, virtual table, or view in the
        // entire schema.
        //
        // schema:     Name of attached database hold this table
        // name:       Name of the table itself
        // type:       "table", "view", "virtual", "shadow"
        // ncol:       Number of columns
        // wr:         True for a WITHOUT ROWID table
        // strict:     True for a STRICT table
        PragTyp_TABLE_LIST => {
            db.pp().nMem = 6;
            sqlite3CodeVerifyNamedSchema(db, zDb.as_deref());
            for ii in 0..db.aDb.len() {
                if let Some(z) = &zDb {
                    if crate::util::sqlite3_stricmp(Some(z), db.aDb[ii].zDbSName.as_deref()) != 0 {
                        continue;
                    }
                }

                // Ensure that the Table.nCol field is initialized for all views
                // and virtual tables.  Each time we initialize a Table.nCol value
                // for a table, that can potentially disrupt the hash table, so
                // restart the initialization scan.
                let mut initNCol = db.aDb[ii].pSchema.borrow().tblHash.count();
                while initNCol > 0 {
                    initNCol -= 1;
                    let tabs = db.aDb[ii].pSchema.borrow().tblHash.values();
                    let mut hit = false;
                    for pTab in tabs.iter() {
                        let (nCol, zName) = {
                            let t = pTab.borrow();
                            (t.nCol, t.zName.clone())
                        };
                        if nCol == 0 {
                            let zSql = mprintf!(db, b"SELECT*FROM\"%w\"", &zName);
                            let mut pDummy: Option<StmtId> = None;
                            let mut zTail = 0usize;
                            let _ = crate::prepare::sqlite3_prepare_v3(
                                db,
                                Some(&zSql),
                                -1,
                                SQLITE_PREPARE_DONT_LOG as u32,
                                &mut pDummy,
                                &mut zTail,
                            );
                            if let Some(id) = pDummy {
                                let _ = crate::vdbeapi::sqlite3_finalize(db, id);
                            }
                            if db.mallocFailed != 0 {
                                errmsg!(db, b"out of memory");
                                db.pp().rc = SQLITE_NOMEM;
                            }
                            hit = true;
                            break;
                        }
                    }
                    if !hit {
                        break;
                    }
                }

                let tabs = db.aDb[ii].pSchema.borrow().tblHash.values();
                for pTab in tabs.iter() {
                    let t = pTab.borrow();
                    if let Some(zr) = zRight {
                        if crate::util::sqlite3_stricmp(Some(zr), Some(&t.zName)) != 0 {
                            continue;
                        }
                    }
                    let zType: &[u8] = if t.IsView() {
                        b"view"
                    } else if t.IsVirtual() {
                        b"virtual"
                    } else if (t.tabFlags & TF_Shadow) != 0 {
                        b"shadow"
                    } else {
                        b"table"
                    };
                    let zPref = crate::build::sqlite3PreferredTableName(Some(&t.zName));
                    let zSName = db.aDb[ii].zDbSName.clone();
                    let args = [
                        PfArg::Str(zSName.as_deref()),
                        PfArg::Str(zPref.as_deref()),
                        PfArg::Str(Some(zType)),
                        PfArg::Int(t.nCol as i64),
                        PfArg::Int(((t.tabFlags & TF_WithoutRowid) != 0) as i64),
                        PfArg::Int(((t.tabFlags & TF_Strict) != 0) as i64),
                    ];
                    drop(t);
                    sqlite3VdbeMultiLoad(db.v(), 1, b"sssiii", &args);
                }
            }
        }

        PragTyp_INDEX_INFO => {
            if let Some(zr) = zRight {
                let mut pIdx = sqlite3FindIndex(db, Some(zr), zDb.as_deref());
                if pIdx.is_none() {
                    // If there is no index named zRight, check to see if there
                    // is a WITHOUT ROWID table named zRight, and if there is,
                    // show the structure of the PRIMARY KEY index for that table.
                    let pTab =
                        sqlite3LocateTable(db, LOCATE_NOERR as u32, Some(zr), zDb.as_deref());
                    if let Some(pTab) = pTab {
                        if !pTab.borrow().HasRowid() {
                            pIdx = sqlite3PrimaryKeyIndex(&pTab);
                        }
                    }
                }
                if let Some(pIdx) = pIdx {
                    let pSchema = pIdx.borrow().pSchema;
                    let iIdxDb = crate::prepare::sqlite3SchemaToIndex(db, pSchema);
                    let mx: i32;
                    if pPragma.iArg != 0 {
                        // PRAGMA index_xinfo (newer version with more rows and columns)
                        mx = pIdx.borrow().nColumn as i32;
                        db.pp().nMem = 6;
                    } else {
                        // PRAGMA index_info (legacy version)
                        mx = pIdx.borrow().nKeyCol as i32;
                        db.pp().nMem = 3;
                    }
                    let pTab = pIdx.borrow().table();
                    sqlite3CodeVerifySchema(db, iIdxDb);
                    let nMem = db.ppr().nMem;
                    for i in 0..mx {
                        let (cnum, sortOrder, zColl, nKeyCol) = {
                            let x = pIdx.borrow();
                            (
                                x.aiColumn[i as usize],
                                x.aSortOrder.get(i as usize).copied().unwrap_or(0),
                                x.azColl.get(i as usize).cloned(),
                                x.nKeyCol as i32,
                            )
                        };
                        let zName = if cnum < 0 {
                            None
                        } else {
                            Some(pTab.borrow().aCol[cnum as usize].zCnName.clone())
                        };
                        sqlite3VdbeMultiLoad(
                            db.v(),
                            1,
                            b"iisX",
                            &[
                                PfArg::Int(i as i64),
                                PfArg::Int(cnum as i64),
                                PfArg::Str(zName.as_deref()),
                            ],
                        );
                        if pPragma.iArg != 0 {
                            sqlite3VdbeMultiLoad(
                                db.v(),
                                4,
                                b"isiX",
                                &[
                                    PfArg::Int(sortOrder as i64),
                                    PfArg::Str(zColl.as_deref()),
                                    PfArg::Int((i < nKeyCol) as i64),
                                ],
                            );
                        }
                        sqlite3VdbeAddOp2(db.v(), OP_ResultRow, 1, nMem);
                    }
                }
            }
        }

        PragTyp_INDEX_LIST => {
            if let Some(zr) = zRight {
                let pTab = sqlite3FindTable(db, Some(zr), zDb.as_deref());
                if let Some(pTab) = pTab {
                    let pSchema = pTab.borrow().pSchema;
                    let iTabDb = crate::prepare::sqlite3SchemaToIndex(db, pSchema);
                    db.pp().nMem = 5;
                    sqlite3CodeVerifySchema(db, iTabDb);
                    let idxs = pTab.borrow().pIndex.clone();
                    for (i, pIdx) in idxs.iter().enumerate() {
                        const azOrigin: [&[u8]; 3] = [b"c", b"u", b"pk"];
                        let (zName, uniq, origin, partial) = {
                            let x = pIdx.borrow();
                            (
                                x.zName.clone(),
                                x.IsUniqueIndex() as i64,
                                azOrigin[x.idxType as usize],
                                x.pPartIdxWhere.is_some() as i64,
                            )
                        };
                        sqlite3VdbeMultiLoad(
                            db.v(),
                            1,
                            b"isisi",
                            &[
                                PfArg::Int(i as i64),
                                PfArg::Str(Some(&zName)),
                                PfArg::Int(uniq),
                                PfArg::Str(Some(origin)),
                                PfArg::Int(partial),
                            ],
                        );
                    }
                }
            }
        }

        PragTyp_DATABASE_LIST => {
            db.pp().nMem = 3;
            for i in 0..db.aDb.len() {
                let Some(pBt) = db.aDb[i].pBt.clone() else {
                    continue;
                };
                debug_assert!(db.aDb[i].zDbSName.is_some());
                let zName = db.aDb[i].zDbSName.clone();
                let zFile = sqlite3BtreeGetFilename(&pBt);
                sqlite3VdbeMultiLoad(
                    db.v(),
                    1,
                    b"iss",
                    &[
                        PfArg::Int(i as i64),
                        PfArg::Str(zName.as_deref()),
                        PfArg::Str(zFile.as_deref()),
                    ],
                );
            }
        }

        PragTyp_COLLATION_LIST => {
            db.pp().nMem = 2;
            let names: Vec<ZStr> = db
                .aCollSeq
                .iter()
                .map(|(_, c)| c[0].zName.clone())
                .collect();
            for (i, zName) in names.iter().enumerate() {
                sqlite3VdbeMultiLoad(
                    db.v(),
                    1,
                    b"is",
                    &[PfArg::Int(i as i64), PfArg::Str(Some(zName))],
                );
            }
        }

        PragTyp_FUNCTION_LIST => {
            let showInternFunc = (db.mDbFlags & DBFLAG_InternalFunc) != 0;
            db.pp().nMem = 6;
            let builtins = db.builtinFuncs.clone();
            for bucket in builtins.a.iter() {
                for chain in bucket.iter() {
                    debug_assert!((chain[0].funcFlags & SQLITE_FUNC_BUILTIN) != 0);
                    pragmaFunclistLine(db.v(), chain, 1, showInternFunc);
                }
            }
            let chains: Vec<Vec<FuncDefRef>> = db.aFunc.values();
            for chain in chains.iter() {
                pragmaFunclistLine(db.v(), chain, 0, showInternFunc);
            }
        }

        PragTyp_MODULE_LIST => {
            db.pp().nMem = 1;
            let names: Vec<ZStr> = db
                .aModule
                .iter()
                .map(|(_, m)| m.borrow().zName.clone())
                .collect();
            for zName in names.iter() {
                sqlite3VdbeMultiLoad(db.v(), 1, b"s", &[PfArg::Str(Some(zName))]);
            }
        }

        PragTyp_PRAGMA_LIST => {
            for p in aPragmaName.iter() {
                sqlite3VdbeMultiLoad(db.v(), 1, b"s", &[PfArg::Str(Some(p.zName))]);
            }
        }

        PragTyp_FOREIGN_KEY_LIST => {
            if let Some(zr) = zRight {
                let pTab = sqlite3FindTable(db, Some(zr), zDb.as_deref());
                if let Some(pTab) = pTab {
                    if pTab.borrow().IsOrdinaryTable() {
                        let fks = pTab.borrow().u.tab.pFKey.clone();
                        if !fks.is_empty() {
                            let pSchema = pTab.borrow().pSchema;
                            let iTabDb = crate::prepare::sqlite3SchemaToIndex(db, pSchema);
                            db.pp().nMem = 8;
                            sqlite3CodeVerifySchema(db, iTabDb);
                            for (i, pFK) in fks.iter().enumerate() {
                                let fk = pFK.borrow().clone();
                                for j in 0..fk.nCol as usize {
                                    let zFrom = pTab.borrow().aCol[fk.aCol[j].iFrom as usize]
                                        .zCnName
                                        .clone();
                                    sqlite3VdbeMultiLoad(
                                        db.v(),
                                        1,
                                        b"iissssss",
                                        &[
                                            PfArg::Int(i as i64),
                                            PfArg::Int(j as i64),
                                            PfArg::Str(Some(&fk.zTo)),
                                            PfArg::Str(Some(&zFrom)),
                                            PfArg::Str(fk.aCol[j].zCol.as_deref()),
                                            PfArg::Str(Some(actionName(fk.aAction[1]))), // ON UPDATE
                                            PfArg::Str(Some(actionName(fk.aAction[0]))), // ON DELETE
                                            PfArg::Str(Some(b"NONE")),
                                        ],
                                    );
                                }
                            }
                        }
                    }
                }
            }
        }

        PragTyp_FOREIGN_KEY_CHECK => {
            let regResult = db.ppr().nMem + 1; // 3 registers to hold a result row
            db.pp().nMem += 4;
            let regRow = {
                let p = db.pp();
                p.nMem += 1;
                p.nMem
            }; // Registers to hold a row from pTab
            let tabs = db.aDb[iDb as usize].pSchema.borrow().tblHash.values();
            let mut kIdx = 0usize;
            let mut k = !tabs.is_empty();
            while k {
                let pTab: Option<TableRef> = if let Some(zr) = zRight {
                    k = false;
                    sqlite3LocateTable(db, 0, Some(zr), zDb.as_deref())
                } else {
                    let t = tabs[kIdx].clone();
                    kIdx += 1;
                    k = kIdx < tabs.len();
                    Some(t)
                };
                let Some(pTab) = pTab else { continue };
                {
                    let t = pTab.borrow();
                    if !t.IsOrdinaryTable() || t.u.tab.pFKey.is_empty() {
                        continue;
                    }
                }
                let (pSchema, tnum, zTabName, nCol, fks, hasRowid) = {
                    let t = pTab.borrow();
                    (
                        t.pSchema,
                        t.tnum,
                        t.zName.clone(),
                        t.nCol as i32,
                        t.u.tab.pFKey.clone(),
                        t.HasRowid(),
                    )
                };
                iDb = crate::prepare::sqlite3SchemaToIndex(db, pSchema);
                zDb = db.aDb[iDb as usize].zDbSName.clone();
                sqlite3CodeVerifySchema(db, iDb);
                sqlite3TableLock(db, iDb, tnum, 0, Some(&zTabName));
                crate::expr::sqlite3TouchRegister(db, nCol + regRow);
                crate::insert::sqlite3OpenTable(db, 0, iDb, &pTab, OP_OpenRead as i32);
                sqlite3VdbeLoadString(db.v(), regResult, &zTabName);
                let mut i = 1;
                let mut brokeOut = false;
                for pFK in fks.iter() {
                    let zTo = pFK.borrow().zTo.clone();
                    let pParent = sqlite3FindTable(db, Some(&zTo), zDb.as_deref());
                    if let Some(pParent) = pParent {
                        let mut pIdx: Option<IndexRef> = None;
                        let (ptnum, pname) = {
                            let p = pParent.borrow();
                            (p.tnum, p.zName.clone())
                        };
                        sqlite3TableLock(db, iDb, ptnum, 0, Some(&pname));
                        let x =
                            crate::fkey::sqlite3FkLocateIndex(db, &pParent, pFK, &mut pIdx, None);
                        if x == 0 {
                            match &pIdx {
                                None => {
                                    crate::insert::sqlite3OpenTable(
                                        db,
                                        i,
                                        iDb,
                                        &pParent,
                                        OP_OpenRead as i32,
                                    );
                                }
                                Some(pIdx) => {
                                    let itnum = pIdx.borrow().tnum;
                                    sqlite3VdbeAddOp3(db.v(), OP_OpenRead, i, itnum as i32, iDb);
                                    sqlite3VdbeSetP4KeyInfo(db, pIdx);
                                }
                            }
                        } else {
                            k = false;
                            brokeOut = true;
                            break;
                        }
                    }
                    i += 1;
                }
                debug_assert!(db.ppr().nErr > 0 || !brokeOut);
                if brokeOut {
                    break;
                }
                if db.ppr().nTab < i {
                    db.pp().nTab = i;
                }
                let addrTop = sqlite3VdbeAddOp1(db.v(), OP_Rewind, 0);
                let mut i = 1;
                for pFK in fks.iter() {
                    let fk = pFK.borrow().clone();
                    let pParent = sqlite3FindTable(db, Some(&fk.zTo), zDb.as_deref());
                    let mut pIdx: Option<IndexRef> = None;
                    let mut aiCols: Option<Vec<i32>> = None;
                    if let Some(pParent) = &pParent {
                        let x = crate::fkey::sqlite3FkLocateIndex(
                            db,
                            pParent,
                            pFK,
                            &mut pIdx,
                            Some(&mut aiCols),
                        );
                        debug_assert!(x == 0 || db.mallocFailed != 0);
                    }
                    let addrOk = sqlite3VdbeMakeLabel(db);

                    // Generate code to read the child key values into registers
                    // regRow..regRow+n. If any of the child key values are NULL,
                    // this row cannot cause an FK violation. Jump directly to
                    // addrOk in this case.
                    crate::expr::sqlite3TouchRegister(db, regRow + fk.nCol);
                    for j in 0..fk.nCol as usize {
                        let iCol = match &aiCols {
                            Some(a) => a[j],
                            None => fk.aCol[j].iFrom,
                        };
                        crate::expr::sqlite3ExprCodeGetColumnOfTable(
                            db,
                            &pTab,
                            0,
                            iCol,
                            regRow + j as i32,
                        );
                        sqlite3VdbeAddOp2(db.v(), OP_IsNull, regRow + j as i32, addrOk);
                    }

                    // Generate code to query the parent index for a matching
                    // parent key. If a match is found, jump to addrOk.
                    if let Some(pIdx) = &pIdx {
                        let zAff =
                            crate::insert::sqlite3IndexAffinityStr(db, pIdx).unwrap_or_default();
                        let n = (fk.nCol as usize).min(zAff.len());
                        sqlite3VdbeAddOp4(
                            db.v(),
                            OP_Affinity,
                            regRow,
                            fk.nCol,
                            0,
                            P4::Z(zAff[..n].to_vec()),
                            fk.nCol,
                        );
                        sqlite3VdbeAddOp4Int(db.v(), OP_Found, i, addrOk, regRow, fk.nCol);
                    } else if pParent.is_some() {
                        let jmp = sqlite3VdbeCurrentAddr(db.v()) + 2;
                        sqlite3VdbeAddOp3(db.v(), OP_SeekRowid, i, jmp, regRow);
                        sqlite3VdbeGoto(db.v(), addrOk);
                        debug_assert!(fk.nCol == 1 || db.mallocFailed != 0);
                    }

                    // Generate code to report an FK violation to the caller.
                    if hasRowid {
                        sqlite3VdbeAddOp2(db.v(), OP_Rowid, 0, regResult + 1);
                    } else {
                        sqlite3VdbeAddOp2(db.v(), OP_Null, 0, regResult + 1);
                    }
                    sqlite3VdbeMultiLoad(
                        db.v(),
                        regResult + 2,
                        b"siX",
                        &[PfArg::Str(Some(&fk.zTo)), PfArg::Int((i - 1) as i64)],
                    );
                    sqlite3VdbeAddOp2(db.v(), OP_ResultRow, regResult, 4);
                    sqlite3VdbeResolveLabel(db.v(), addrOk);
                    i += 1;
                }
                sqlite3VdbeAddOp2(db.v(), OP_Next, 0, addrTop + 1);
                sqlite3VdbeJumpHere(db.v(), addrTop);
            }
        }

        // Reinstall the LIKE and GLOB functions.  The variant of LIKE
        // used will be case sensitive or not depending on the RHS.
        PragTyp_CASE_SENSITIVE_LIKE => {
            if let Some(zr) = zRight {
                let b = sqlite3GetBoolean(Some(zr), 0) as i32;
                crate::func::sqlite3RegisterLikeFunctions(db, b);
            }
        }

        // PRAGMA integrity_check
        // PRAGMA integrity_check(N)
        // PRAGMA quick_check
        // PRAGMA quick_check(N)
        //
        // Verify the integrity of the database.
        //
        // The "quick_check" is reduced version of
        // integrity_check designed to detect most database corruption
        // without the overhead of cross-checking indexes.  Quick_check
        // is linear time whereas integrity_check is O(NlogN).
        //
        // The maximum number of errors is 100 by default.  A different
        // default can be specified using a numeric parameter N.
        //
        // Or, the parameter N can be the name of a table.  In that case,
        // only the one table named is verified.  The freelist is only
        // verified if the named table is "sqlite_schema" (or one of its
        // aliases).
        //
        // All schemas are checked by default.  To check just a single
        // schema, use the form:
        //
        //      PRAGMA schema.integrity_check;
        PragTyp_INTEGRITY_CHECK => {
            pragmaIntegrityCheck(db, &zLeft, zRight, pId2, pValue, iDb);
        }

        // PRAGMA encoding
        // PRAGMA encoding = "utf-8"|"utf-16"|"utf-16le"|"utf-16be"
        //
        // In its first form, this pragma returns the encoding of the main
        // database. If the database is not initialized, it is initialized
        // now.
        //
        // The second form of this pragma is a no-op if the main database
        // file has not already been initialized. In this case it sets the
        // default encoding that will be used for the main database file if
        // a new file is created. If an existing main database file is
        // opened, then the default text encoding for the existing database
        // is used.
        //
        // In all cases new databases created using the ATTACH command are
        // created to use the same default text encoding as the main
        // database. If the main database has not been initialized and/or
        // created when ATTACH is executed, this is done before the ATTACH
        // operation.
        //
        // In the second form this pragma sets the text encoding to be used
        // in new database files created using this database handle. It is
        // only useful if invoked immediately after the main database i
        PragTyp_ENCODING => {
            const encnames: [(&[u8], u8); 8] = [
                (b"UTF8", SQLITE_UTF8),
                (b"UTF-8", SQLITE_UTF8),       // Must be element [1]
                (b"UTF-16le", SQLITE_UTF16LE), // Must be element [2]
                (b"UTF-16be", SQLITE_UTF16BE), // Must be element [3]
                (b"UTF16le", SQLITE_UTF16LE),
                (b"UTF16be", SQLITE_UTF16BE),
                (b"UTF-16", 0), // SQLITE_UTF16NATIVE
                (b"UTF16", 0),  // SQLITE_UTF16NATIVE
            ];
            match zRight {
                None => {
                    // "PRAGMA encoding"
                    if crate::prepare::sqlite3ReadSchema(db) != 0 {
                        return;
                    }
                    let e = db.ENC() as usize;
                    returnSingleText(db.v(), Some(encnames[e].0));
                }
                Some(zr) => {
                    // "PRAGMA encoding = XXX"
                    // Only change the value of sqlite.enc if the database handle
                    // is not initialized. If the main database exists, the new
                    // sqlite.enc value will be overwritten when the schema is next
                    // loaded. If it does not already exists, it will be created
                    // to use the new encoding value.
                    if (db.mDbFlags & DBFLAG_EncodingFixed) == 0 {
                        let mut found = false;
                        for &(zName, e) in encnames.iter() {
                            if 0 == sqlite3StrICmp(Some(zr), Some(zName)) {
                                let enc = if e != 0 { e } else { SQLITE_UTF16NATIVE };
                                db.aDb[0].pSchema.borrow_mut().enc = enc; // SCHEMA_ENC(db) = enc
                                crate::callback::sqlite3SetTextEncoding(db, enc);
                                found = true;
                                break;
                            }
                        }
                        if !found {
                            errmsg!(db, b"unsupported encoding: %s", zr);
                        }
                    }
                }
            }
        }

        // PRAGMA [schema.]schema_version
        // PRAGMA [schema.]schema_version = <integer>
        //
        // PRAGMA [schema.]user_version
        // PRAGMA [schema.]user_version = <integer>
        //
        // PRAGMA [schema.]freelist_count
        //
        // PRAGMA [schema.]data_version
        //
        // PRAGMA [schema.]application_id
        // PRAGMA [schema.]application_id = <integer>
        //
        // The pragma's schema_version and user_version are used to set or
        // get the value of the schema-version and user-version,
        // respectively. Both the schema-version and the user-version are
        // 32-bit signed integers stored in the database header.
        //
        // The schema-cookie is usually only manipulated internally by
        // SQLite. It is incremented by SQLite whenever the database schema
        // is modified (by creating or dropping a table or index). The
        // schema version is used by SQLite each time a query is executed to
        // ensure that the internal cache of the schema used when compiling
        // the SQL query matches the schema of the database against which
        // the compiled query is actually executed.  Subverting this
        // mechanism by using "PRAGMA schema_version" to modify the
        // schema-version is potentially dangerous and may lead to program
        // crashes or database corruption. Use with caution!
        //
        // The user-version is not used internally by SQLite. It may be used
        // by applications for any purpose.
        PragTyp_HEADER_VALUE => {
            let iCookie = pPragma.iArg as i32; // Which cookie to read or write
            sqlite3VdbeUsesBtree(db.v(), iDb);
            match zRight {
                Some(zr) if (pPragma.mPragFlg & PragFlg_ReadOnly) == 0 => {
                    // Write the specified cookie value
                    const setCookie: [VdbeOpList; 2] = [
                        VdbeOpList {
                            opcode: OP_Transaction,
                            p1: 0,
                            p2: 1,
                            p3: 0,
                        }, // 0
                        VdbeOpList {
                            opcode: OP_SetCookie,
                            p1: 0,
                            p2: 0,
                            p3: 0,
                        }, // 1
                    ];
                    let a = sqlite3VdbeAddOpList(db.v(), &setCookie, 0);
                    let val = sqlite3Atoi(Some(zr));
                    op(db, a).p1 = iDb;
                    op(db, a + 1).p1 = iDb;
                    op(db, a + 1).p2 = iCookie;
                    op(db, a + 1).p3 = val;
                    op(db, a + 1).p5 = 1;
                    if iCookie == BTREE_SCHEMA_VERSION && (db.flags & SQLITE_Defensive) != 0 {
                        // Do not allow the use of PRAGMA schema_version=VALUE in
                        // defensive mode.  Change the OP_SetCookie opcode into a
                        // no-op.
                        op(db, a + 1).opcode = OP_Noop;
                    }
                }
                _ => {
                    // Read the specified cookie value
                    const readCookie: [VdbeOpList; 3] = [
                        VdbeOpList {
                            opcode: OP_Transaction,
                            p1: 0,
                            p2: 0,
                            p3: 0,
                        }, // 0
                        VdbeOpList {
                            opcode: OP_ReadCookie,
                            p1: 0,
                            p2: 1,
                            p3: 0,
                        }, // 1
                        VdbeOpList {
                            opcode: OP_ResultRow,
                            p1: 1,
                            p2: 1,
                            p3: 0,
                        },
                    ];
                    let a = sqlite3VdbeAddOpList(db.v(), &readCookie, 0);
                    op(db, a).p1 = iDb;
                    op(db, a + 1).p1 = iDb;
                    op(db, a + 1).p3 = iCookie;
                    sqlite3VdbeReusable(db.v());
                }
            }
        }

        // PRAGMA compile_options
        //
        // Return the names of all compile-time options used in this build,
        // one option per row.
        PragTyp_COMPILE_OPTIONS => {
            let mut i = 0;
            db.pp().nMem = 1;
            while let Some(zOpt) = crate::mainapi::sqlite3_compileoption_get(i) {
                i += 1;
                sqlite3VdbeLoadString(db.v(), 1, &zOpt);
                sqlite3VdbeAddOp2(db.v(), OP_ResultRow, 1, 1);
            }
            sqlite3VdbeReusable(db.v());
        }

        // PRAGMA [schema.]wal_checkpoint = passive|full|restart|truncate
        //
        // Checkpoint the database.
        PragTyp_WAL_CHECKPOINT => {
            let iBt = if pId2.z.is_some() { iDb } else { SQLITE_MAX_DB };
            let mut eMode = SQLITE_CHECKPOINT_PASSIVE;
            if let Some(zr) = zRight {
                if sqlite3StrICmp(Some(zr), Some(b"full")) == 0 {
                    eMode = SQLITE_CHECKPOINT_FULL;
                } else if sqlite3StrICmp(Some(zr), Some(b"restart")) == 0 {
                    eMode = SQLITE_CHECKPOINT_RESTART;
                } else if sqlite3StrICmp(Some(zr), Some(b"truncate")) == 0 {
                    eMode = SQLITE_CHECKPOINT_TRUNCATE;
                } else if sqlite3StrICmp(Some(zr), Some(b"noop")) == 0 {
                    eMode = SQLITE_CHECKPOINT_NOOP;
                }
            }
            db.pp().nMem = 3;
            sqlite3VdbeAddOp3(db.v(), OP_Checkpoint, iBt, eMode, 1);
            sqlite3VdbeAddOp2(db.v(), OP_ResultRow, 1, 3);
        }

        // PRAGMA wal_autocheckpoint
        // PRAGMA wal_autocheckpoint = N
        //
        // Configure a database connection to automatically checkpoint a
        // database after accumulating N frames in the log. Or query for the
        // current value of N.
        PragTyp_WAL_AUTOCHECKPOINT => {
            if let Some(zr) = zRight {
                crate::mainapi::sqlite3_wal_autocheckpoint(db, sqlite3Atoi(Some(zr)));
            }
            let n = if db.xWalCallback.is_some() {
                db.walAutoCkpt
            } else {
                0
            };
            returnSingleInt(db.v(), n as i64);
        }

        // PRAGMA shrink_memory
        //
        // IMPLEMENTATION-OF: R-23445-46109 This pragma causes the database
        // connection on which it is invoked to free up as much memory as it
        // can, by calling sqlite3_db_release_memory().
        PragTyp_SHRINK_MEMORY => {
            crate::mainapi::sqlite3_db_release_memory(db);
        }

        // PRAGMA optimize
        // PRAGMA optimize(MASK)
        // PRAGMA schema.optimize
        // PRAGMA schema.optimize(MASK)
        //
        // Attempt to optimize the database.  All schemas are optimized in
        // the first two forms, and only the specified schema is optimized
        // in the latter two.
        //
        // The details of optimizations performed by this pragma are expected
        // to change and improve over time.  Applications should anticipate
        // that this pragma will perform new optimizations in future
        // releases.
        //
        // The optional argument is a bitmask of optimizations to perform:
        //
        //    0x00001    Debugging mode.  Do not actually perform any
        //               optimizations but instead return one line of text for
        //               each optimization that would have been done.  Off by
        //               default.
        //
        //    0x00002    Run ANALYZE on tables that might benefit.  On by
        //               default.
        //
        //    0x00010    Run all ANALYZE operations using an analysis_limit
        //               that is the lessor of the current analysis_limit and
        //               the SQLITE_DEFAULT_OPTIMIZE_LIMIT compile-time option.
        //
        //    0x10000    Look at tables to see if they need to be reanalyzed
        //               due to growth or shrinkage even if they have not been
        //               queried during the current connection.  Off by
        //               default.
        //
        // The default MASK is and always shall be 0x0fffe.
        //
        // DETERMINATION OF WHEN TO RUN ANALYZE
        //
        // In the current implementation, a table is analyzed if only if all
        // of the following are true:
        //
        // (1) MASK bit 0x00002 is set.
        //
        // (2) The table is an ordinary table, not a virtual table or view.
        //
        // (3) The table name does not begin with "sqlite_".
        //
        // (4) One or more of the following is true:
        //      (4a) The 0x10000 MASK bit is set.
        //      (4b) One or more indexes on the table lacks an entry
        //           in the sqlite_stat1 table.
        //      (4c) The query planner used sqlite_stat1-style statistics for
        //           one or more indexes of the table at some point during the
        //           lifetime of the current connection.
        //
        // (5) One or more of the following is true:
        //      (5a) One or more indexes on the table lacks an entry
        //           in the sqlite_stat1 table.  (Same as 4a)
        //      (5b) The number of rows in the table has increased or
        //           decreased by 10-fold.  In other words, the current size
        //           of the table is 10 times larger than the size in
        //           sqlite_stat1 or else the current size is less than 1/10th
        //           the size in sqlite_stat1.
        PragTyp_OPTIMIZE => {
            pragmaOptimize(db, zRight, zDb.as_deref(), iDb);
        }

        // PRAGMA soft_heap_limit
        // PRAGMA soft_heap_limit = N
        //
        // IMPLEMENTATION-OF: R-26343-45930 This pragma invokes the
        // sqlite3_soft_heap_limit64() interface with the argument N, if N is
        // specified and is a non-negative integer.
        // IMPLEMENTATION-OF: R-64451-07163 The soft_heap_limit pragma always
        // returns the same integer that would be returned by the
        // sqlite3_soft_heap_limit64(-1) C-language function.
        PragTyp_SOFT_HEAP_LIMIT => {
            let mut N: i64 = 0;
            if let Some(zr) = zRight {
                if sqlite3DecOrHexToI64(Some(zr), &mut N) == SQLITE_OK {
                    crate::mainapi::sqlite3_soft_heap_limit64(N);
                }
            }
            let x = crate::mainapi::sqlite3_soft_heap_limit64(-1);
            returnSingleInt(db.v(), x);
        }

        // PRAGMA hard_heap_limit
        // PRAGMA hard_heap_limit = N
        //
        // Invoke sqlite3_hard_heap_limit64() to query or set the hard heap
        // limit.  The hard heap limit can be activated or lowered by this
        // pragma, but not raised or deactivated.  Only the
        // sqlite3_hard_heap_limit64() C-language API can raise or deactivate
        // the hard heap limit.  This allows an application to set a heap
        // limit constraint that cannot be relaxed by an untrusted SQL script.
        PragTyp_HARD_HEAP_LIMIT => {
            let mut N: i64 = 0;
            if let Some(zr) = zRight {
                if sqlite3DecOrHexToI64(Some(zr), &mut N) == SQLITE_OK {
                    let iPrior = crate::mainapi::sqlite3_hard_heap_limit64(-1);
                    if N > 0 && (iPrior == 0 || iPrior > N) {
                        crate::mainapi::sqlite3_hard_heap_limit64(N);
                    }
                }
            }
            let x = crate::mainapi::sqlite3_hard_heap_limit64(-1);
            returnSingleInt(db.v(), x);
        }

        // PRAGMA threads
        // PRAGMA threads = N
        //
        // Configure the maximum number of worker threads.  Return the new
        // maximum, which might be less than requested.
        PragTyp_THREADS => {
            let mut N: i64 = 0;
            if let Some(zr) = zRight {
                if sqlite3DecOrHexToI64(Some(zr), &mut N) == SQLITE_OK && N >= 0 {
                    crate::mainapi::sqlite3_limit(
                        db,
                        SQLITE_LIMIT_WORKER_THREADS,
                        (N & 0x7fffffff) as i32,
                    );
                }
            }
            let x = crate::mainapi::sqlite3_limit(db, SQLITE_LIMIT_WORKER_THREADS, -1);
            returnSingleInt(db.v(), x as i64);
        }

        // PRAGMA analysis_limit
        // PRAGMA analysis_limit = N
        //
        // Configure the maximum number of rows that ANALYZE will examine
        // in each index that it looks at.  Return the new limit.
        PragTyp_ANALYSIS_LIMIT => {
            let mut N: i64 = 0;
            if let Some(zr) = zRight {
                if sqlite3DecOrHexToI64(Some(zr), &mut N) == SQLITE_OK // IMP: R-40975-20399
                    && N >= 0
                {
                    db.nAnalysisLimit = (N & 0x7fffffff) as i32;
                }
            }
            let x = db.nAnalysisLimit;
            returnSingleInt(db.v(), x as i64); // IMP: R-57594-65522
        }

        // PRAGMA busy_timeout
        // PRAGMA busy_timeout = N
        //
        // Call sqlite3_busy_timeout(db, N).  Return the current timeout value
        // if one is set.  If no busy handler or a different busy handler is
        // set then 0 is returned.  Setting the busy_timeout to 0 or negative
        // disables the timeout.
        /* PragTyp_BUSY_TIMEOUT */
        _ => {
            let mut n = 0;
            debug_assert!(pPragma.ePragTyp == PragTyp_BUSY_TIMEOUT);
            if zRight.is_some() && sqlite3GetInt32(zRight, &mut n) != 0 {
                crate::mainapi::sqlite3_busy_timeout(db, n);
            }
            let t = db.busyTimeout;
            returnSingleInt(db.v(), t as i64);
        }
    } // End of the PRAGMA switch

    // The following block is a no-op unless SQLITE_DEBUG is defined. Its
    // only purpose is to execute assert() statements to verify that if the
    // PragFlg_NoColumns1 flag is set and the caller specified an argument
    // to the PRAGMA, the implementation has not added any OP_ResultRow
    // instructions to the VM.
    let _ = id2n;
}

/// PRAGMA integrity_check / quick_check (the PragTyp_INTEGRITY_CHECK case
/// of sqlite3Pragma(), moved into its own function).
fn pragmaIntegrityCheck(
    db: &mut Sqlite3,
    zLeft: &[u8],
    zRight: Option<&[u8]>,
    pId2: &Token,
    pValue: &Token,
    iDb: i32,
) {
    let mut iDb = iDb;
    let mut pObjTab: Option<TableRef> = None; // Check only this one table, if not NULL

    let isQuick = sqlite3Tolower(zLeft.first().copied().unwrap_or(0)) == b'q';

    // If the PRAGMA command was of the form "PRAGMA <db>.integrity_check",
    // then iDb is set to the index of the database identified by <db>.
    // In this case, the integrity of database iDb only is verified by
    // the VDBE created below.
    //
    // Otherwise, if the command was simply "PRAGMA integrity_check" (or
    // "PRAGMA quick_check"), then iDb is set to 0. In this case, set iDb
    // to -1 here, to indicate that the VDBE should verify the integrity
    // of all attached databases.
    debug_assert!(iDb >= 0);
    debug_assert!(iDb == 0 || pId2.z.is_some());
    if pId2.z.is_none() {
        iDb = -1;
    }

    // Initialize the VDBE program
    db.pp().nMem = 6;

    // Set the maximum error count
    let mut mxErr = SQLITE_INTEGRITY_CHECK_ERROR_MAX;
    if let Some(zr) = zRight {
        // C: sqlite3GetInt32(pValue->z, &mxErr) reads the token text (up to
        // the end of the SQL; trailing characters are ignored).
        let zv = match &pValue.z {
            Some(s) => &s[pValue.off as usize..],
            None => zr,
        };
        if sqlite3GetInt32(Some(zv), &mut mxErr) != 0 {
            if mxErr <= 0 {
                mxErr = SQLITE_INTEGRITY_CHECK_ERROR_MAX;
            }
        } else {
            let zDbName = if iDb >= 0 {
                db.aDb[iDb as usize].zDbSName.clone()
            } else {
                None
            };
            pObjTab = sqlite3LocateTable(db, 0, Some(zr), zDbName.as_deref());
        }
    }
    sqlite3VdbeAddOp2(db.v(), OP_Integer, mxErr - 1, 1); // reg[1] holds errors left

    // Do an integrity check on each database file
    for i in 0..db.nDb() {
        if iDb >= 0 && i != iDb {
            continue;
        }

        sqlite3CodeVerifySchema(db, i);
        db.pp().okConstFactor = 0; // tag-20230327-1

        // Do an integrity check of the B-Tree
        //
        // Begin by finding the root pages numbers
        // for all tables and indices in the database.
        let pTbls: Vec<TableRef> = db.aDb[i as usize].pSchema.borrow().tblHash.values();
        let mut cnt = 0usize;
        for pTab in pTbls.iter() {
            if tableSkipIntegrityCheck(pTab, pObjTab.as_ref()) {
                continue;
            }
            let t = pTab.borrow();
            if t.HasRowid() {
                cnt += 1;
            }
            cnt += t.pIndex.len();
        }
        if cnt == 0 {
            continue;
        }
        if pObjTab.is_some() {
            cnt += 1;
        }
        let mut aRoot: Vec<u32> = vec![0; cnt + 1];
        cnt = 0;
        if pObjTab.is_some() {
            cnt += 1;
            aRoot[cnt] = 0;
        }
        for pTab in pTbls.iter() {
            if tableSkipIntegrityCheck(pTab, pObjTab.as_ref()) {
                continue;
            }
            let t = pTab.borrow();
            if t.HasRowid() {
                cnt += 1;
                aRoot[cnt] = t.tnum;
            }
            for pIdx in t.pIndex.iter() {
                cnt += 1;
                aRoot[cnt] = pIdx.borrow().tnum;
            }
        }
        aRoot[0] = cnt as u32;
        let cnt = cnt as i32;

        // Make sure sufficient number of registers have been allocated
        crate::expr::sqlite3TouchRegister(db, 8 + cnt);
        sqlite3VdbeAddOp3(db.v(), OP_Null, 0, 8, 8 + cnt);
        crate::expr::sqlite3ClearTempRegCache(db);

        // Do the b-tree integrity checks
        sqlite3VdbeAddOp4(
            db.v(),
            OP_IntegrityCk,
            1,
            cnt,
            8,
            P4::Ai(Rc::new(aRoot)),
            P4_INTARRAY as i32,
        );
        sqlite3VdbeChangeP5(db.v(), i as u16);
        let addr = sqlite3VdbeAddOp1(db.v(), OP_IsNull, 2);
        let zDbSName = db.aDb[i as usize].zDbSName.clone();
        let zMsg = mprintf!(db, b"*** in database %s ***\n", zDbSName.as_deref());
        sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zMsg), P4_DYNAMIC as i32);
        sqlite3VdbeAddOp3(db.v(), OP_Concat, 2, 3, 3);
        integrityCheckResultRow(db.v());
        sqlite3VdbeJumpHere(db.v(), addr);

        // Check that the indexes all have the right number of rows
        let mut cnt: i32 = if pObjTab.is_some() { 1 } else { 0 };
        sqlite3VdbeLoadString(db.v(), 2, b"wrong # of entries in index ");
        for pTab in pTbls.iter() {
            let mut iTab: i32;
            if tableSkipIntegrityCheck(pTab, pObjTab.as_ref()) {
                continue;
            }
            let idxs = pTab.borrow().pIndex.clone();
            if pTab.borrow().HasRowid() {
                iTab = cnt;
                cnt += 1;
            } else {
                iTab = cnt;
                for pIdx in idxs.iter() {
                    if pIdx.borrow().IsPrimaryKeyIndex() {
                        break;
                    }
                    iTab += 1;
                }
            }
            for pIdx in idxs.iter() {
                let (partial, zName) = {
                    let x = pIdx.borrow();
                    (x.pPartIdxWhere.is_some(), x.zName.clone())
                };
                if !partial {
                    let addr = sqlite3VdbeAddOp3(db.v(), OP_Eq, 8 + cnt, 0, 8 + iTab);
                    sqlite3VdbeLoadString(db.v(), 4, &zName);
                    sqlite3VdbeAddOp3(db.v(), OP_Concat, 4, 2, 3);
                    integrityCheckResultRow(db.v());
                    sqlite3VdbeJumpHere(db.v(), addr);
                }
                cnt += 1;
            }
        }

        // Make sure all the indices are constructed correctly.
        for pTab in pTbls.iter() {
            let mut pPrior: Option<IndexRef> = None; // Previous index
            let mut iDataCur = 0;
            let mut iIdxCur = 0;
            let mut r1 = -1;
            let r2: i32; // Previous key for WITHOUT ROWID tables
            let mut mxCol: i32; // Maximum non-virtual column number

            if tableSkipIntegrityCheck(pTab, pObjTab.as_ref()) {
                continue;
            }
            if !pTab.borrow().IsOrdinaryTable() {
                continue;
            }
            let hasRowid = pTab.borrow().HasRowid();
            let pPk: Option<IndexRef> = if isQuick || hasRowid {
                r2 = 0;
                None
            } else {
                let pPk = sqlite3PrimaryKeyIndex(pTab).expect("pk");
                let nKeyCol = pPk.borrow().nKeyCol as i32;
                r2 = crate::expr::sqlite3GetTempRange(db, nKeyCol);
                sqlite3VdbeAddOp3(db.v(), OP_Null, 1, r2, r2 + nKeyCol - 1);
                Some(pPk)
            };
            crate::insert::sqlite3OpenTableAndIndices(
                db,
                pTab,
                OP_OpenRead as i32,
                0,
                1,
                None,
                &mut iDataCur,
                &mut iIdxCur,
            );
            // reg[7] counts the number of entries in the table.
            // reg[8+i] counts the number of entries in the i-th index
            sqlite3VdbeAddOp2(db.v(), OP_Integer, 0, 7);
            let idxs = pTab.borrow().pIndex.clone();
            for j in 0..idxs.len() as i32 {
                sqlite3VdbeAddOp2(db.v(), OP_Integer, 0, 8 + j); // index entries counter
            }
            sqlite3VdbeAddOp2(db.v(), OP_Rewind, iDataCur, 0);
            let loopTop = sqlite3VdbeAddOp2(db.v(), OP_AddImm, 7, 1);

            // Fetch the right-most column from the table.  This will cause
            // the entire record header to be parsed and sanity checked.  It
            // will also prepopulate the cursor column cache that is used
            // by the OP_IsType code, so it is a required step.
            debug_assert!(!pTab.borrow().IsVirtual());
            if hasRowid {
                let t = pTab.borrow();
                mxCol = -1;
                for j in 0..t.nCol as usize {
                    if (t.aCol[j].colFlags & COLFLAG_VIRTUAL) == 0 {
                        mxCol += 1;
                    }
                }
                if mxCol == t.iPKey as i32 {
                    mxCol -= 1;
                }
            } else {
                // COLFLAG_VIRTUAL columns are not included in the WITHOUT ROWID
                // PK index column-count, so there is no need to account for them
                // in this case.
                mxCol = sqlite3PrimaryKeyIndex(pTab).expect("pk").borrow().nColumn as i32 - 1;
            }
            if mxCol >= 0 {
                sqlite3VdbeAddOp3(db.v(), OP_Column, iDataCur, mxCol, 3);
                sqlite3VdbeTypeofColumn(db.v(), 3);
            }

            if !isQuick {
                if let Some(pPk) = &pPk {
                    // Verify WITHOUT ROWID keys are in ascending order
                    let nKeyCol = pPk.borrow().nKeyCol as i32;
                    let a1 = sqlite3VdbeAddOp4Int(db.v(), OP_IdxGT, iDataCur, 0, r2, nKeyCol);
                    sqlite3VdbeAddOp1(db.v(), OP_IsNull, r2);
                    let zTabName = pTab.borrow().zName.clone();
                    let zErr = mprintf!(db, b"row not in PRIMARY KEY order for %s", &zTabName);
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                    integrityCheckResultRow(db.v());
                    sqlite3VdbeJumpHere(db.v(), a1);
                    sqlite3VdbeJumpHere(db.v(), a1 + 1);
                    for j in 0..nKeyCol {
                        crate::expr::sqlite3ExprCodeLoadIndexColumn(db, pPk, iDataCur, j, r2 + j);
                    }
                }
            }
            // Verify datatypes for all columns:
            //
            //   (1) NOT NULL columns may not contain a NULL
            //   (2) Datatype must be exact for non-ANY columns in STRICT tables
            //   (3) Datatype for TEXT columns in non-STRICT tables must be
            //       NULL, TEXT, or BLOB.
            //   (4) Datatype for numeric columns in non-STRICT tables must not
            //       be a TEXT value that can be losslessly converted to numeric.
            let (bStrict, nCol, iPKey, zTabName) = {
                let t = pTab.borrow();
                (
                    (t.tabFlags & TF_Strict) != 0,
                    t.nCol as i32,
                    t.iPKey as i32,
                    t.zName.clone(),
                )
            };
            for j in 0..nCol {
                let pCol = pTab.borrow().aCol[j as usize].clone(); // The column to be checked
                let p1: i32;
                let p3: i32;
                let mut p4: i32; // Operands to the OP_IsType opcode

                if j == iPKey {
                    continue;
                }
                let doTypeCheck = if bStrict {
                    pCol.eCType > COLTYPE_ANY
                } else {
                    pCol.affinity > SQLITE_AFF_BLOB
                };
                if pCol.notNull == 0 && !doTypeCheck {
                    continue;
                }

                // Compute the operands that will be needed for OP_IsType
                p4 = SQLITE_NULL;
                if (pCol.colFlags & COLFLAG_VIRTUAL) != 0 {
                    crate::expr::sqlite3ExprCodeGetColumnOfTable(db, pTab, iDataCur, j, 3);
                    p1 = -1;
                    p3 = 3;
                } else {
                    if pCol.iDflt != 0 {
                        let mut pDfltValue: Option<Box<Mem>> = None;
                        let e = crate::build::sqlite3ColumnExprAuth(db, pTab, j as usize);
                        let enc = db.ENC();
                        crate::vdbemem::sqlite3ValueFromExpr(
                            db,
                            e,
                            enc,
                            pCol.affinity,
                            &mut pDfltValue,
                        );
                        if let Some(mut v) = pDfltValue {
                            p4 = crate::vdbeapi::sqlite3_value_type(&mut v);
                            crate::vdbemem::sqlite3ValueFree(db, &mut v);
                        }
                    }
                    p1 = iDataCur;
                    if !hasRowid {
                        let pk = sqlite3PrimaryKeyIndex(pTab).expect("pk");
                        p3 = crate::build::sqlite3TableColumnToIndex(&pk, j);
                    } else {
                        p3 = crate::build::sqlite3TableColumnToStorage(pTab, j as i16) as i32;
                    }
                }

                let labelError = sqlite3VdbeMakeLabel(db);
                let labelOk = sqlite3VdbeMakeLabel(db);
                if pCol.notNull != 0 {
                    // (1) NOT NULL columns may not contain a NULL
                    let jmp3;
                    let jmp2 = sqlite3VdbeAddOp4Int(db.v(), OP_IsType, p1, labelOk, p3, p4);
                    if p1 < 0 {
                        sqlite3VdbeChangeP5(db.v(), 0x0f); // INT, REAL, TEXT, or BLOB
                        jmp3 = jmp2;
                    } else {
                        sqlite3VdbeChangeP5(db.v(), 0x0d); // INT, TEXT, or BLOB
                        // OP_IsType does not detect NaN values in the database
                        // file which should be treated as a NULL.  So if the
                        // header type is REAL, we have to load the actual data
                        // using OP_Column to reliably determine if the value is
                        // a NULL.
                        sqlite3VdbeAddOp3(db.v(), OP_Column, p1, p3, 3);
                        crate::update::sqlite3ColumnDefault(db, pTab, j, 3);
                        jmp3 = sqlite3VdbeAddOp2(db.v(), OP_NotNull, 3, labelOk);
                    }
                    let zErr = mprintf!(db, b"NULL value in %s.%s", &zTabName, &pCol.zCnName);
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                    if doTypeCheck {
                        sqlite3VdbeGoto(db.v(), labelError);
                        sqlite3VdbeJumpHere(db.v(), jmp2);
                        sqlite3VdbeJumpHere(db.v(), jmp3);
                    } else {
                        // VDBE byte code will fall thru
                    }
                }
                if bStrict && doTypeCheck {
                    // (2) Datatype must be exact for non-ANY columns in STRICT
                    // tables
                    const aStdTypeMask: [u8; 6] = [
                        0x1f, // ANY
                        0x18, // BLOB
                        0x11, // INT
                        0x11, // INTEGER
                        0x13, // REAL
                        0x14, // TEXT
                    ];
                    sqlite3VdbeAddOp4Int(db.v(), OP_IsType, p1, labelOk, p3, p4);
                    debug_assert!(pCol.eCType >= 1 && pCol.eCType as usize <= aStdTypeMask.len());
                    sqlite3VdbeChangeP5(db.v(), aStdTypeMask[(pCol.eCType - 1) as usize] as u16);
                    let zErr = mprintf!(
                        db,
                        b"non-%s value in %s.%s",
                        sqlite3StdType[(pCol.eCType - 1) as usize],
                        &zTabName,
                        &pCol.zCnName
                    );
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                } else if !bStrict && pCol.affinity == SQLITE_AFF_TEXT {
                    // (3) Datatype for TEXT columns in non-STRICT tables must be
                    //     NULL, TEXT, or BLOB.
                    sqlite3VdbeAddOp4Int(db.v(), OP_IsType, p1, labelOk, p3, p4);
                    sqlite3VdbeChangeP5(db.v(), 0x1c); // NULL, TEXT, or BLOB
                    let zErr = mprintf!(db, b"NUMERIC value in %s.%s", &zTabName, &pCol.zCnName);
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                } else if !bStrict && pCol.affinity >= SQLITE_AFF_NUMERIC {
                    // (4) Datatype for numeric columns in non-STRICT tables must
                    //     not be a TEXT value that can be converted to numeric.
                    sqlite3VdbeAddOp4Int(db.v(), OP_IsType, p1, labelOk, p3, p4);
                    sqlite3VdbeChangeP5(db.v(), 0x1b); // NULL, INT, FLOAT, or BLOB
                    if p1 >= 0 {
                        crate::expr::sqlite3ExprCodeGetColumnOfTable(db, pTab, iDataCur, j, 3);
                    }
                    sqlite3VdbeAddOp4(
                        db.v(),
                        OP_Affinity,
                        3,
                        1,
                        0,
                        P4::Z(b"C".to_vec()),
                        P4_STATIC as i32,
                    );
                    sqlite3VdbeAddOp4Int(db.v(), OP_IsType, -1, labelOk, 3, p4);
                    sqlite3VdbeChangeP5(db.v(), 0x1c); // NULL, TEXT, or BLOB
                    let zErr = mprintf!(db, b"TEXT value in %s.%s", &zTabName, &pCol.zCnName);
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                }
                sqlite3VdbeResolveLabel(db.v(), labelError);
                integrityCheckResultRow(db.v());
                sqlite3VdbeResolveLabel(db.v(), labelOk);
            }
            // Verify CHECK constraints
            let hasCheck = pTab.borrow().pCheck.is_some();
            if hasCheck && (db.flags & SQLITE_IgnoreChecks) == 0 {
                let ck = pTab.borrow().pCheck.clone();
                let ckId = db.tree(&ck);
                let pCheck = crate::expr::sqlite3ExprListDup(db, ckId, 0);
                if db.mallocFailed == 0 {
                    let addrCkFault = sqlite3VdbeMakeLabel(db);
                    let addrCkOk = sqlite3VdbeMakeLabel(db);
                    db.pp().iSelfTab = iDataCur + 1;
                    let nExpr = db.el(pCheck).nExpr();
                    let mut k = nExpr - 1;
                    while k > 0 {
                        let e = db.el(pCheck).a[k as usize].pExpr;
                        crate::expr::sqlite3ExprIfFalse(db, e, addrCkFault, 0);
                        k -= 1;
                    }
                    let e0 = db.el(pCheck).a[0].pExpr;
                    crate::expr::sqlite3ExprIfTrue(db, e0, addrCkOk, SQLITE_JUMPIFNULL as i32);
                    sqlite3VdbeResolveLabel(db.v(), addrCkFault);
                    db.pp().iSelfTab = 0;
                    let zErr = mprintf!(db, b"CHECK constraint failed in %s", &zTabName);
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zErr), P4_DYNAMIC as i32);
                    integrityCheckResultRow(db.v());
                    sqlite3VdbeResolveLabel(db.v(), addrCkOk);
                }
                crate::expr::sqlite3ExprListDelete(db, pCheck);
            }
            if !isQuick {
                // Omit the remaining tests for quick_check
                // Validate index entries for the current row
                for (j, pIdx) in idxs.iter().enumerate() {
                    let j = j as i32;
                    let mut jmp3 = 0;
                    if let Some(pk) = &pPk {
                        if Rc::ptr_eq(pk, pIdx) {
                            continue;
                        }
                    }
                    let ckUniq = sqlite3VdbeMakeLabel(db);
                    r1 = crate::delete::sqlite3GenerateIndexKey(
                        db,
                        pIdx,
                        iDataCur,
                        0,
                        0,
                        Some(&mut jmp3),
                        pPrior.as_ref(),
                        r1,
                    );
                    pPrior = Some(pIdx.clone());
                    let (nColumn, nKeyCol, zIdxName, isUnique, aiColumn, azColl) = {
                        let x = pIdx.borrow();
                        (
                            x.nColumn as i32,
                            x.nKeyCol as i32,
                            x.zName.clone(),
                            x.IsUniqueIndex(),
                            x.aiColumn.clone(),
                            x.azColl.clone(),
                        )
                    };
                    sqlite3VdbeAddOp2(db.v(), OP_AddImm, 8 + j, 1); // increment entry count
                    // Verify that an index entry exists for the current table row
                    sqlite3VdbeAddOp4Int(db.v(), OP_Found, iIdxCur + j, ckUniq, r1, nColumn);
                    let jmp2 = sqlite3VdbeAddOp3(db.v(), OP_IFindKey, iIdxCur + j, ckUniq, r1);
                    sqlite3VdbeChangeP4(db.v(), -1, P4::Idx(pIdx.clone()), P4_INDEX as i32);
                    let zMsg = mprintf!(
                        db,
                        b"index %s stores an imprecise floating-point value for row ",
                        &zIdxName
                    );
                    sqlite3VdbeAddOp4(db.v(), OP_String8, 0, 3, 0, P4::Z(zMsg), P4_DYNAMIC as i32);
                    sqlite3VdbeAddOp3(db.v(), OP_Concat, 7, 3, 3);
                    integrityCheckResultRow(db.v());
                    sqlite3VdbeAddOp2(db.v(), OP_Goto, 0, ckUniq);

                    sqlite3VdbeJumpHere(db.v(), jmp2);
                    sqlite3VdbeLoadString(db.v(), 3, b"row ");
                    sqlite3VdbeAddOp3(db.v(), OP_Concat, 7, 3, 3);
                    sqlite3VdbeLoadString(db.v(), 4, b" missing from index ");
                    sqlite3VdbeAddOp3(db.v(), OP_Concat, 4, 3, 3);
                    let jmp5 = sqlite3VdbeLoadString(db.v(), 4, &zIdxName);
                    sqlite3VdbeAddOp3(db.v(), OP_Concat, 4, 3, 3);
                    let jmp4 = integrityCheckResultRow(db.v());
                    sqlite3VdbeResolveLabel(db.v(), ckUniq);

                    // The OP_IdxRowid opcode is an optimized version of OP_Column
                    // that extracts the rowid off the end of the index record.
                    // But it only works correctly if index record does not have
                    // any extra bytes at the end.  Verify that this is the case.
                    if hasRowid {
                        sqlite3VdbeAddOp2(db.v(), OP_IdxRowid, iIdxCur + j, 3);
                        let jmp7 = sqlite3VdbeAddOp3(db.v(), OP_Eq, 3, 0, r1 + nColumn - 1);
                        sqlite3VdbeLoadString(db.v(), 3, b"rowid not at end-of-record for row ");
                        sqlite3VdbeAddOp3(db.v(), OP_Concat, 7, 3, 3);
                        sqlite3VdbeLoadString(db.v(), 4, b" of index ");
                        sqlite3VdbeGoto(db.v(), jmp5 - 1);
                        sqlite3VdbeJumpHere(db.v(), jmp7);
                    }

                    // Any indexed columns with non-BINARY collations must still
                    // hold the exact same text value as the table.
                    let mut label6 = 0;
                    for kk in 0..nKeyCol {
                        // C compares the pointer with sqlite3StrBINARY.
                        if azColl[kk as usize].as_slice() == sqlite3StrBINARY {
                            continue;
                        }
                        if label6 == 0 {
                            label6 = sqlite3VdbeMakeLabel(db);
                        }
                        sqlite3VdbeAddOp3(db.v(), OP_Column, iIdxCur + j, kk, 3);
                        sqlite3VdbeAddOp3(db.v(), OP_Ne, 3, label6, r1 + kk);
                    }
                    if label6 != 0 {
                        let jmp6 = sqlite3VdbeAddOp0(db.v(), OP_Goto);
                        sqlite3VdbeResolveLabel(db.v(), label6);
                        sqlite3VdbeLoadString(db.v(), 3, b"row ");
                        sqlite3VdbeAddOp3(db.v(), OP_Concat, 7, 3, 3);
                        sqlite3VdbeLoadString(db.v(), 4, b" values differ from index ");
                        sqlite3VdbeGoto(db.v(), jmp5 - 1);
                        sqlite3VdbeJumpHere(db.v(), jmp6);
                    }

                    // For UNIQUE indexes, verify that only one entry exists with
                    // the current key.  The entry is unique if (1) any column is
                    // NULL or (2) the next entry has a different key
                    if isUnique {
                        let uniqOk = sqlite3VdbeMakeLabel(db);
                        for kk in 0..nKeyCol {
                            let iCol = aiColumn[kk as usize] as i32;
                            debug_assert!(iCol != XN_ROWID as i32 && iCol < nCol);
                            if iCol >= 0 && pTab.borrow().aCol[iCol as usize].notNull != 0 {
                                continue;
                            }
                            sqlite3VdbeAddOp2(db.v(), OP_IsNull, r1 + kk, uniqOk);
                        }
                        let jmp6 = sqlite3VdbeAddOp1(db.v(), OP_Next, iIdxCur + j);
                        sqlite3VdbeGoto(db.v(), uniqOk);
                        sqlite3VdbeJumpHere(db.v(), jmp6);
                        sqlite3VdbeAddOp4Int(db.v(), OP_IdxGT, iIdxCur + j, uniqOk, r1, nKeyCol);
                        sqlite3VdbeLoadString(db.v(), 3, b"non-unique entry in index ");
                        sqlite3VdbeGoto(db.v(), jmp5);
                        sqlite3VdbeResolveLabel(db.v(), uniqOk);
                    }
                    sqlite3VdbeJumpHere(db.v(), jmp4);
                    crate::delete::sqlite3ResolvePartIdxLabel(db, jmp3);
                }
            }
            sqlite3VdbeAddOp2(db.v(), OP_Next, iDataCur, loopTop);
            sqlite3VdbeJumpHere(db.v(), loopTop - 1);
            if let Some(pPk) = &pPk {
                debug_assert!(!isQuick);
                let nKeyCol = pPk.borrow().nKeyCol as i32;
                crate::expr::sqlite3ReleaseTempRange(db, r2, nKeyCol);
            }
        }

        // Second pass to invoke the xIntegrity method on all virtual
        // tables.
        for pTab in pTbls.iter() {
            if tableSkipIntegrityCheck(pTab, pObjTab.as_ref()) {
                continue;
            }
            let (isOrd, isVirt, nCol, zMod) = {
                let t = pTab.borrow();
                (
                    t.IsOrdinaryTable(),
                    t.IsVirtual(),
                    t.nCol,
                    t.u.vtab.azArg.first().cloned().unwrap_or_default(),
                )
            };
            if isOrd {
                continue;
            }
            if !isVirt {
                continue;
            }
            if nCol <= 0 && db.aModule.find(&zMod).is_none() {
                continue;
            }
            crate::build::sqlite3ViewGetColumnNames(db, pTab);
            let pVTab = pTab.borrow().u.vtab.p.first().cloned();
            let Some(pVTab) = pVTab else { continue };
            let (pVtab, iVersion) = {
                let v = pVTab.borrow();
                (v.pVtab.clone(), v.pMod.borrow().pModule.iVersion())
            };
            let Some(pVtab) = pVtab else { continue };
            if iVersion < 4 {
                continue;
            }
            if !pVtab.borrow().has_xIntegrity() {
                continue;
            }
            sqlite3VdbeAddOp3(db.v(), OP_VCheck, i, 3, isQuick as i32);
            pTab.borrow_mut().nTabRef += 1;
            sqlite3VdbeAppendP4(db.v(), P4::Tab(pTab.clone()), P4_TABLEREF as i32);
            let a1 = sqlite3VdbeAddOp1(db.v(), OP_IsNull, 3);
            integrityCheckResultRow(db.v());
            sqlite3VdbeJumpHere(db.v(), a1);
        }
    }
    {
        const endCode: [VdbeOpList; 7] = [
            VdbeOpList {
                opcode: OP_AddImm,
                p1: 1,
                p2: 0,
                p3: 0,
            }, // 0
            VdbeOpList {
                opcode: OP_IfNotZero,
                p1: 1,
                p2: 4,
                p3: 0,
            }, // 1
            VdbeOpList {
                opcode: OP_String8,
                p1: 0,
                p2: 3,
                p3: 0,
            }, // 2
            VdbeOpList {
                opcode: OP_ResultRow,
                p1: 3,
                p2: 1,
                p3: 0,
            }, // 3
            VdbeOpList {
                opcode: OP_Halt,
                p1: 0,
                p2: 0,
                p3: 0,
            }, // 4
            VdbeOpList {
                opcode: OP_String8,
                p1: 0,
                p2: 3,
                p3: 0,
            }, // 5
            VdbeOpList {
                opcode: OP_Goto,
                p1: 0,
                p2: 3,
                p3: 0,
            }, // 6
        ];
        let a = sqlite3VdbeAddOpList(db.v(), &endCode, 0);
        op(db, a).p2 = 1 - mxErr;
        {
            let o = op(db, a + 2);
            o.p4type = P4_STATIC;
            o.p4 = P4::Z(b"ok".to_vec());
        }
        {
            let o = op(db, a + 5);
            o.p4type = P4_STATIC;
            o.p4 = P4::Z(crate::mainapi::sqlite3ErrStr(SQLITE_CORRUPT).unwrap_or_default());
        }
        let cur = sqlite3VdbeCurrentAddr(db.v());
        sqlite3VdbeChangeP3(db.v(), 0, cur - 2);
    }
}

/// PRAGMA optimize (the PragTyp_OPTIMIZE case of sqlite3Pragma()).
fn pragmaOptimize(db: &mut Sqlite3, zRight: Option<&[u8]>, zDb: Option<&[u8]>, iDb: i32) {
    let mut iDb = iDb;
    let mut nCheck = 0; // Number of tables to be optimized
    let mut nBtree = 0; // Number of btrees to scan
    let opMask: u32; // Mask of operations to perform
    let mut nLimit: i32; // Analysis limit to use

    if let Some(zr) = zRight {
        opMask = sqlite3Atoi(Some(zr)) as u32;
        if (opMask & 0x02) == 0 {
            return;
        }
    } else {
        opMask = 0xfffe;
    }
    if (opMask & 0x10) == 0 {
        nLimit = 0;
    } else if db.nAnalysisLimit > 0 && db.nAnalysisLimit < SQLITE_DEFAULT_OPTIMIZE_LIMIT {
        nLimit = 0;
    } else {
        nLimit = SQLITE_DEFAULT_OPTIMIZE_LIMIT;
    }
    let iTabCur = {
        let p = db.pp();
        let c = p.nTab;
        p.nTab += 1;
        c
    }; // Cursor for a table whose size needs checking
    let iDbLast = if zDb.is_some() { iDb } else { db.nDb() - 1 };
    while iDb <= iDbLast {
        if iDb == 1 {
            iDb += 1;
            continue;
        }
        sqlite3CodeVerifySchema(db, iDb);
        let tabs = db.aDb[iDb as usize].pSchema.borrow().tblHash.values();
        for pTab in tabs.iter() {
            let (ordinary, zName, nRowLogEst, tabFlags, idxs) = {
                let t = pTab.borrow();
                (
                    t.IsOrdinaryTable(),
                    t.zName.clone(),
                    t.nRowLogEst,
                    t.tabFlags,
                    t.pIndex.clone(),
                )
            };

            // This only works for ordinary tables
            if !ordinary {
                continue;
            }

            // Do not scan system tables
            if zName.len() >= 7 && zName[..7].eq_ignore_ascii_case(b"sqlite_") {
                continue;
            }

            // Find the size of the table as last recorded in sqlite_stat1.
            // If any index is unanalyzed, then the threshold is -1 to
            // indicate a new, unanalyzed index
            let mut szThreshold: LogEst = nRowLogEst;
            let mut nIndex = 0;
            for pIdx in idxs.iter() {
                nIndex += 1;
                if pIdx.borrow().hasStat1 == 0 {
                    szThreshold = -1; // Always analyze if any index lacks statistics
                }
            }

            // If table pTab has not been used in a way that would benefit
            // from having analysis statistics during the current session,
            // then skip it, unless the 0x10000 MASK bit is set.
            if (tabFlags & TF_MaybeReanalyze) != 0 {
                // Check for size change if stat1 has been used for a query
            } else if (opMask & 0x10000) != 0 {
                // Check for size change if 0x10000 is set
            } else if !idxs.is_empty() && szThreshold < 0 {
                // Do analysis if unanalyzed indexes exists
            } else {
                // Otherwise, we can skip this table
                continue;
            }

            nCheck += 1;
            if nCheck == 2 {
                // If ANALYZE might be invoked two or more times, hold a write
                // transaction for efficiency
                sqlite3BeginWriteOperation(db, 0, iDb);
            }
            nBtree += nIndex + 1;

            // Reanalyze if the table is 10 times larger or smaller than
            // the last analysis.  Unconditional reanalysis if there are
            // unanalyzed indexes.
            crate::insert::sqlite3OpenTable(db, iTabCur, iDb, pTab, OP_OpenRead as i32);
            if szThreshold >= 0 {
                const iRange: LogEst = 33; // 10x size change
                let a = sqlite3VdbeCurrentAddr(db.v()) + 2 + (opMask & 1) as i32;
                sqlite3VdbeAddOp4Int(
                    db.v(),
                    OP_IfSizeBetween,
                    iTabCur,
                    a,
                    if szThreshold >= iRange {
                        (szThreshold - iRange) as i32
                    } else {
                        -1
                    },
                    (szThreshold + iRange) as i32,
                );
            } else {
                let a = sqlite3VdbeCurrentAddr(db.v()) + 2 + (opMask & 1) as i32;
                sqlite3VdbeAddOp2(db.v(), OP_Rewind, iTabCur, a);
            }
            let zDbSName = db.aDb[iDb as usize].zDbSName.clone();
            let zSubSql = mprintf!(db, b"ANALYZE \"%w\".\"%w\"", zDbSName.as_deref(), &zName);
            if (opMask & 0x01) != 0 {
                let r1 = crate::expr::sqlite3GetTempReg(db);
                sqlite3VdbeAddOp4(
                    db.v(),
                    OP_String8,
                    0,
                    r1,
                    0,
                    P4::Z(zSubSql),
                    P4_DYNAMIC as i32,
                );
                sqlite3VdbeAddOp2(db.v(), OP_ResultRow, r1, 1);
            } else {
                sqlite3VdbeAddOp4(
                    db.v(),
                    OP_SqlExec,
                    if nLimit != 0 { 0x02 } else { 0 },
                    nLimit,
                    0,
                    P4::Z(zSubSql),
                    P4_DYNAMIC as i32,
                );
            }
        }
        iDb += 1;
    }
    sqlite3VdbeAddOp0(db.v(), OP_Expire);

    // In a schema with a large number of tables and indexes, scale back
    // the analysis_limit to avoid excess run-time in the worst case.
    if db.mallocFailed == 0 && nLimit > 0 && nBtree > 100 {
        nLimit = 100 * nLimit / nBtree;
        if nLimit < 100 {
            nLimit = 100;
        }
        let v = db.v();
        let iEnd = sqlite3VdbeCurrentAddr(v);
        for iAddr in 0..iEnd as usize {
            if v.aOp[iAddr].opcode == OP_SqlExec {
                v.aOp[iAddr].p2 = nLimit;
            }
        }
    }
}

// ---------------------------------------------------------------------------
// Implementation of an eponymous virtual table that runs a pragma.
// ---------------------------------------------------------------------------

/// The pragma virtual table module (C pragmaVtabModule with pAux = the
/// PragmaName).
struct PragmaVtabModule {
    pName: &'static PragmaName,
}

/// struct PragmaVtab
struct PragmaVtab {
    /// C base.zErrMsg
    zErrMsg: Option<ZStr>,
    /// Name of the pragma
    pName: &'static PragmaName,
    /// Number of hidden columns
    nHidden: u8,
    /// Index of the first hidden column
    iHidden: u8,
}

/// struct PragmaVtabCursor
struct PragmaVtabCursor {
    /// C pVtab->zErrMsg (see VtabCursor::zErrMsg)
    zErrMsg: Option<ZStr>,
    pName: &'static PragmaName,
    iHidden: u8,
    /// The pragma statement to run
    pPragma: Option<StmtId>,
    /// Current rowid
    iRowid: i64,
    /// Value of the argument and schema
    azArg: [Option<ZStr>; 2],
}

impl crate::vtab::VtabModule for PragmaVtabModule {
    fn iVersion(&self) -> i32 {
        0
    }
    fn has_xCreate(&self) -> bool {
        false
    }
    fn has_xDestroy(&self) -> bool {
        false
    }

    /// Pragma virtual table module xConnect method.
    fn xConnect(
        &self,
        db: &mut Sqlite3,
        _argv: &[&[u8]],
        pzErr: &mut Option<ZStr>,
    ) -> Result<Box<dyn crate::vtab::Vtab>, i32> {
        let pPragma = self.pName;
        let mut cSep = b'(';
        let mut acc: Vec<u8> = b"CREATE TABLE x".to_vec();
        let mut i = 0;
        let mut j = pPragma.iPragCName as usize;
        while i < pPragma.nPragCName as usize {
            acc.push(cSep);
            acc.push(b'"');
            acc.extend_from_slice(pragCName[j]);
            acc.push(b'"');
            cSep = b',';
            i += 1;
            j += 1;
        }
        if i == 0 {
            acc.extend_from_slice(b"(\"");
            acc.extend_from_slice(pPragma.zName);
            acc.push(b'"');
            i += 1;
        }
        let mut jj = 0;
        if (pPragma.mPragFlg & PragFlg_Result1) != 0 {
            acc.extend_from_slice(b",arg HIDDEN");
            jj += 1;
        }
        if (pPragma.mPragFlg & (PragFlg_SchemaOpt | PragFlg_SchemaReq)) != 0 {
            acc.extend_from_slice(b",schema HIDDEN");
            jj += 1;
        }
        acc.push(b')');
        let rc = crate::vtab::sqlite3_declare_vtab(db, Some(&acc));
        if rc == SQLITE_OK {
            Ok(Box::new(PragmaVtab {
                zErrMsg: None,
                pName: pPragma,
                iHidden: i as u8,
                nHidden: jj as u8,
            }))
        } else {
            *pzErr = crate::mainapi::sqlite3_errmsg(db);
            Err(rc)
        }
    }
}

impl crate::vtab::Vtab for PragmaVtab {
    /// Figure out the best index to use to search a pragma virtual table.
    ///
    /// There are not really any index choices.  But we want to encourage
    /// the query planner to give == constraints on as many hidden
    /// parameters as possible, and especially on the first hidden
    /// parameter.  So return a high cost if hidden parameters are
    /// unconstrained.
    fn xBestIndex(&mut self, _db: &mut Sqlite3, pIdxInfo: &mut crate::vtab::IndexInfo) -> i32 {
        pIdxInfo.estimatedCost = 1.0;
        if self.nHidden == 0 {
            return SQLITE_OK;
        }
        let mut seen = [0usize; 2];
        for (i, pConstraint) in pIdxInfo.aConstraint.iter().enumerate() {
            if pConstraint.iColumn < self.iHidden as i32 {
                continue;
            }
            if pConstraint.op as i32 != SQLITE_INDEX_CONSTRAINT_EQ {
                continue;
            }
            if pConstraint.usable == 0 {
                return SQLITE_CONSTRAINT;
            }
            let j = (pConstraint.iColumn - self.iHidden as i32) as usize;
            debug_assert!(j < 2);
            seen[j] = i + 1;
        }
        if seen[0] == 0 {
            pIdxInfo.estimatedCost = 2147483647.0;
            pIdxInfo.estimatedRows = 2147483647;
            return SQLITE_OK;
        }
        let j = seen[0] - 1;
        pIdxInfo.aConstraintUsage[j].argvIndex = 1;
        pIdxInfo.aConstraintUsage[j].omit = 1;
        pIdxInfo.estimatedCost = 20.0;
        pIdxInfo.estimatedRows = 20;
        if seen[1] != 0 {
            let j = seen[1] - 1;
            pIdxInfo.aConstraintUsage[j].argvIndex = 2;
            pIdxInfo.aConstraintUsage[j].omit = 1;
        }
        SQLITE_OK
    }

    /// Create a new cursor for the pragma virtual table
    fn xOpen(&mut self, _db: &mut Sqlite3) -> Result<Box<dyn crate::vtab::VtabCursor>, i32> {
        Ok(Box::new(PragmaVtabCursor {
            zErrMsg: None,
            pName: self.pName,
            iHidden: self.iHidden,
            pPragma: None,
            iRowid: 0,
            azArg: [None, None],
        }))
    }

    fn zErrMsg(&mut self) -> &mut Option<ZStr> {
        &mut self.zErrMsg
    }
}

impl PragmaVtabCursor {
    /// Clear all content from pragma virtual table cursor.
    fn pragmaVtabCursorClear(&mut self, db: &mut Sqlite3) {
        if let Some(st) = self.pPragma.take() {
            crate::vdbeapi::sqlite3_finalize(db, st);
        }
        self.iRowid = 0;
        self.azArg = [None, None];
    }
}

impl crate::vtab::VtabCursor for PragmaVtabCursor {
    /// Pragma virtual table module xFilter method.
    fn xFilter(
        &mut self,
        db: &mut Sqlite3,
        _idxNum: i32,
        _idxStr: Option<&[u8]>,
        argv: &mut [Mem],
    ) -> i32 {
        self.pragmaVtabCursorClear(db);
        let mut j = if (self.pName.mPragFlg & PragFlg_Result1) != 0 {
            0
        } else {
            1
        };
        for a in argv.iter_mut() {
            let zText = crate::vdbeapi::sqlite3_value_text(a).map(|z| z.to_vec());
            debug_assert!(j < 2);
            debug_assert!(self.azArg[j].is_none());
            if let Some(z) = zText {
                self.azArg[j] = Some(z);
            }
            j += 1;
        }
        let mut acc: Vec<u8> = b"PRAGMA ".to_vec();
        if let Some(a1) = &self.azArg[1] {
            acc.extend(crate::printf::sqlite3_mprintf(
                b"%Q.",
                &[PfArg::Str(Some(a1))],
            ));
        }
        acc.extend_from_slice(self.pName.zName);
        if let Some(a0) = &self.azArg[0] {
            acc.extend(crate::printf::sqlite3_mprintf(
                b"=%Q",
                &[PfArg::Str(Some(a0))],
            ));
        }
        if acc.len() > db.aLimit[SQLITE_LIMIT_SQL_LENGTH as usize] as usize {
            return SQLITE_NOMEM;
        }
        let mut pStmt: Option<StmtId> = None;
        let mut tail = 0usize;
        let rc = crate::prepare::sqlite3_prepare_v2(db, Some(&acc), -1, &mut pStmt, &mut tail);
        self.pPragma = pStmt;
        if rc != SQLITE_OK {
            self.zErrMsg = crate::mainapi::sqlite3_errmsg(db);
            return rc;
        }
        self.xNext(db)
    }

    /// Advance the pragma virtual table cursor to the next row
    fn xNext(&mut self, db: &mut Sqlite3) -> i32 {
        let mut rc = SQLITE_OK;

        // Increment the xRowid value
        self.iRowid += 1;
        let st = self.pPragma.expect("pragma statement");
        if SQLITE_ROW != crate::vdbeapi::sqlite3_step(db, st) {
            rc = crate::vdbeapi::sqlite3_finalize(db, st);
            self.pPragma = None;
            self.pragmaVtabCursorClear(db);
        }
        rc
    }

    /// Pragma virtual table module xEof method.
    fn xEof(&mut self) -> bool {
        self.pPragma.is_none()
    }

    /// The xColumn method simply returns the corresponding column from the
    /// PRAGMA.
    fn xColumn(&mut self, ctx: &mut Context, i: i32) -> i32 {
        if i < self.iHidden as i32 {
            let st = self.pPragma.expect("pragma statement");
            let mut v = crate::vdbeapi::sqlite3_column_value(ctx.db, st, i)
                .cloned()
                .unwrap_or_default();
            crate::vdbeapi::sqlite3_result_value(ctx, &mut v);
        } else {
            let z = self.azArg[(i - self.iHidden as i32) as usize].clone();
            crate::vdbeapi::sqlite3_result_text(ctx, z.as_deref(), -1);
        }
        SQLITE_OK
    }

    /// Pragma virtual table module xRowid method.
    fn xRowid(&mut self, p: &mut i64) -> i32 {
        *p = self.iRowid;
        SQLITE_OK
    }

    /// Close a pragma virtual table cursor
    fn xCloseDb(&mut self, db: &mut Sqlite3) -> i32 {
        self.pragmaVtabCursorClear(db);
        SQLITE_OK
    }

    fn zErrMsg(&mut self) -> Option<&mut Option<ZStr>> {
        Some(&mut self.zErrMsg)
    }
}

/// C: `Module * sqlite3PragmaVtabRegister(sqlite3 *db, const char *zName)`
///
/// Check to see if zTabName is really the name of a pragma.  If it is,
/// then register an eponymous virtual table for that pragma and return
/// a pointer to the Module object for the new virtual table.
pub fn sqlite3PragmaVtabRegister(db: &mut Sqlite3, zName: Option<&[u8]>) -> Option<ModuleRef> {
    let zName = zName?;
    debug_assert!(zName.len() >= 7 && zName[..7].eq_ignore_ascii_case(b"pragma_"));
    let pName = pragmaLocate(&zName[7.min(zName.len())..])?;
    if (pName.mPragFlg & (PragFlg_Result0 | PragFlg_Result1)) == 0 {
        return None;
    }
    debug_assert!(db.aModule.find(zName).is_none());
    crate::vtab::sqlite3VtabCreateModule(db, zName, Some(Rc::new(PragmaVtabModule { pName })), None)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn pragma_table_sorted() {
        for w in aPragmaName.windows(2) {
            assert!(w[0].zName < w[1].zName);
        }
        assert_eq!(aPragmaName.len(), 66);
    }

    #[test]
    fn journal_modes() {
        assert_eq!(sqlite3JournalModename(0).unwrap(), b"delete");
        assert_eq!(sqlite3JournalModename(5).unwrap(), b"wal");
        assert_eq!(sqlite3JournalModename(6), None);
    }

    #[test]
    fn safety_level() {
        assert_eq!(getSafetyLevel(b"full", 0, 1), 2);
        assert_eq!(getSafetyLevel(b"EXTRA", 0, 1), 3);
        assert_eq!(getSafetyLevel(b"extra", 1, 1), 1);
        assert_eq!(getSafetyLevel(b"off", 0, 1), 0);
        assert_eq!(getSafetyLevel(b"bogus", 0, 7), 7);
    }
}
